# :command.normalize_input
# :command.normalize_input_function
normalize_input() {
  local arg passthru flags
  passthru=false

  while [[ $# -gt 0 ]]; do
    arg="$1"
    if [[ $passthru == true ]]; then
      input+=("$arg")
    elif [[ $arg =~ ^(--[a-zA-Z0-9_\-]+)=(.+)$ ]]; then
      input+=("${BASH_REMATCH[1]}")
      input+=("${BASH_REMATCH[2]}")
    elif [[ $arg =~ ^(-[a-zA-Z0-9])=(.+)$ ]]; then
      input+=("${BASH_REMATCH[1]}")
      input+=("${BASH_REMATCH[2]}")
    elif [[ $arg =~ ^-([a-zA-Z0-9][a-zA-Z0-9]+)$ ]]; then
      flags="${BASH_REMATCH[1]}"
      for ((i = 0; i < ${#flags}; i++)); do
        input+=("-${flags:i:1}")
      done
    elif [[ "$arg" == "--" ]]; then
      passthru=true
      input+=("$arg")
    else
      input+=("$arg")
    fi

    shift
  done
}

# :command.inspect_args
inspect_args() {
  local k

  if ((${#args[@]})); then
    readarray -t sorted_keys < <(printf '%s\n' "${!args[@]}" | LC_ALL=C sort)
    echo args:
    for k in "${sorted_keys[@]}"; do
      echo "- \${args[$k]} = ${args[$k]}"
    done
  else
    echo args: none
  fi

  if ((${#deps[@]})); then
    readarray -t sorted_keys < <(printf '%s\n' "${!deps[@]}" | LC_ALL=C sort)
    echo
    echo deps:
    for k in "${sorted_keys[@]}"; do
      echo "- \${deps[$k]} = ${deps[$k]}"
    done
  fi

  if ((${#env_var_names[@]})); then
    readarray -t sorted_names < <(printf '%s\n' "${env_var_names[@]}" | LC_ALL=C sort)
    echo
    echo "environment variables:"
    for k in "${sorted_names[@]}"; do
      echo "- \$$k = ${!k:-}"
    done
  fi
}

# :command.user_lib
# src/lib/backup_core.sh
# Snapshot of PIV state. Shared by backup, provision and refresh.

# new_backup_dir SERIAL -> prints <root>/<serial>-<timestamp>
new_backup_dir() {
  local dir
  dir="$(backup_root)/$1-$(date '+%Y%m%d-%H%M%S')"
  mkdir -p "$dir"
  printf '%s' "$dir"
}

# write_snapshot SERIAL DIR LABEL
# Writes device-info.txt, piv-info-LABEL.txt and per-slot cert / pubkey / key-info.
# Slots without a cert/key are skipped silently. Never changes the device.
write_snapshot() {
  local serial=$1 dir=$2 label=${3:-before} slot
  yk "$serial" info >"$dir/device-info.txt"
  yk "$serial" piv info >"$dir/piv-info-$label.txt"
  for slot in "${SLOTS[@]}"; do
    yk "$serial" piv certificates export "$slot" "$dir/$slot-cert.pem" 2>/dev/null ||
      rm -f "$dir/$slot-cert.pem"
    yk "$serial" piv keys export "$slot" "$dir/$slot-pubkey.pem" 2>/dev/null ||
      rm -f "$dir/$slot-pubkey.pem"
    yk "$serial" piv keys info "$slot" >"$dir/$slot-key-info.txt" 2>/dev/null ||
      rm -f "$dir/$slot-key-info.txt"
  done
}

# src/lib/chuid.sh
# CHUID save/restore. On firmware < 5.8, changing a certificate regenerates the
# CHUID; we restore the original afterwards (and on abnormal exit).

CHUID_FILE=""
CHUID_SERIAL=""
CHUID_DIRTY=0

# chuid_save SERIAL FILE -> 0 if saved
chuid_save() {
  if yk "$1" piv objects export "$CHUID_OBJECT" "$2" >/dev/null 2>&1; then
    CHUID_SERIAL="$1"
    CHUID_FILE="$2"
    return 0
  fi
  return 1
}

# Call right before the first certificate change.
chuid_mark_dirty() { CHUID_DIRTY=1; }

# chuid_restore: import saved CHUID and verify it round-trips.
chuid_restore() {
  [[ -n "$CHUID_FILE" ]] || return 0
  local check="$TMP_DIR/chuid-after.bin"
  yk "$CHUID_SERIAL" piv objects import --pin "$YK_PIN" "$CHUID_OBJECT" "$CHUID_FILE"
  yk "$CHUID_SERIAL" piv objects export "$CHUID_OBJECT" "$check"
  cmp -s "$CHUID_FILE" "$check" || return 1
  CHUID_DIRTY=0
}

chuid_restore_on_exit() {
  ((CHUID_DIRTY)) && [[ -n "$CHUID_FILE" && -n "$YK_PIN" ]] || return 0
  clack_log_warn "Attempting to restore original CHUID on YubiKey $CHUID_SERIAL..."
  yk "$CHUID_SERIAL" piv objects import --pin "$YK_PIN" "$CHUID_OBJECT" "$CHUID_FILE" \
    >/dev/null 2>&1 || true
}

chuid_forget() {
  CHUID_FILE=""
  CHUID_SERIAL=""
  CHUID_DIRTY=0
}

