# Detect Unicode support
__clack_detect_unicode() {
    case "${LC_ALL:-${LC_CTYPE:-${LANG:-}}}" in
        *UTF-8*|*utf8*) return 0 ;;
        *) return 1 ;;
    esac
}

if __clack_detect_unicode; then
    CLACK_UNICODE=1
else
    CLACK_UNICODE=0
fi

# ============================================================================
# SYMBOLS
# ============================================================================

if ((CLACK_UNICODE == 1)); then
    S_STEP_ACTIVE="◆"
    S_STEP_CANCEL="■"
    S_STEP_ERROR="▲"
