# ============================================================================
# COLORS (ANSI Escape Codes)
# ============================================================================

C_RESET=$'\033[0m'
C_BOLD=$'\033[1m'
C_DIM=$'\033[2m'
C_ITALIC=$'\033[3m'
C_UNDERLINE=$'\033[4m'
C_INVERSE=$'\033[7m'
C_STRIKETHROUGH=$'\033[9m'
C_RED=$'\033[31m'
C_GREEN=$'\033[32m'
C_YELLOW=$'\033[33m'
C_BLUE=$'\033[34m'
C_MAGENTA=$'\033[35m'
C_CYAN=$'\033[36m'
C_WHITE=$'\033[37m'
C_GRAY=$'\033[90m'
C_BLACK=$'\033[30m'
C_BG_CYAN=$'\033[46m'
C_BG_WHITE=$'\033[47m'

# ============================================================================
# CURSOR CONTROL
# ============================================================================

__clack_cursor_hide() { printf '\033[?25l' >&2; }
__clack_cursor_show() { printf '\033[?25h' >&2; }
__clack_cursor_save() { printf '\0337' >&2; }
__clack_cursor_restore() { printf '\0338' >&2; }
__clack_cursor_up() { printf '\033[%dA' "${1:-1}" >&2; }
__clack_cursor_down() { printf '\033[%dB' "${1:-1}" >&2; }
__clack_cursor_to_col() { printf '\033[%dG' "${1:-0}" >&2; }
__clack_erase_line() { printf '\033[2K' >&2; }
__clack_erase_down() { printf '\033[0J' >&2; }

__clack_clear_lines() {
    local n=${1:-1}
    local i
    for ((i = 0; i < n; i++)); do
        __clack_cursor_up 1
        __clack_erase_line
    done
    __clack_cursor_to_col 0
}

# ============================================================================
# INTERNAL HELPERS
# ============================================================================

__clack_print() { printf '%b\n' "$1" >&2; }
__clack_print_n() { printf '%b' "$1" >&2; }

__CLACK_FIELD_SEP=$'\x1f'

__clack_parse_option() {
    local raw="$1"
    local value label hint disabled

    if [[ "$raw" == *"|"* ]]; then
        IFS='|' read -r value label hint disabled <<<"$raw"
        if [[ -z "$label" ]]; then
            label="$value"
        fi
    else
        value="$raw"
        label="$raw"
        hint=""
        disabled=""
    fi

    local disabled_flag=0
    local disabled_lc
    disabled_lc=$(printf '%s' "${disabled}" | tr '[:upper:]' '[:lower:]')
    case "$disabled_lc" in
        1|true|yes|y|disabled) disabled_flag=1 ;;
    esac

    printf '%s%s%s%s%s%s%s' "$value" "$__CLACK_FIELD_SEP" "$label" "$__CLACK_FIELD_SEP" "$hint" "$__CLACK_FIELD_SEP" "$disabled_flag"
}

__clack_find_next_enabled() {
    local __disabled_arr_name=$1
    local start=$2
    local dir=$3
    local count=$4

    local idx=$start
    local n
    for ((n = 0; n < count; n++)); do
        idx=$((idx + dir))
        if ((idx < 0)); then idx=$((count - 1)); fi
        if ((idx >= count)); then idx=0; fi
        local __disabled_val=0
        eval "__disabled_val=\${${__disabled_arr_name}[$idx]}"
        if ((${__disabled_val:-0} == 0)); then
            printf '%s' "$idx"
            return 0
        fi
    done

    printf '%s' "$start"
}

__clack_to_lower() {
    printf '%s' "$1" | tr '[:upper:]' '[:lower:]'
}

__clack_wrap_text() {
    local width=$1
    shift
    local text="$*"
    local out=""
    local line

    # Process each line separately
    while IFS= read -r line || [[ -n "$line" ]]; do
        if [[ -z "$line" ]]; then
            out+=$'\n'
            continue
        fi

        local current=""
        local word
        # Use default IFS for word splitting
        for word in $line; do
            if [[ -z "$current" ]]; then
                current="$word"
                continue
            fi

            if ((${#current} + 1 + ${#word} <= width)); then
                current="$current $word"
            else
                out+="$current"$'\n'
                current="$word"
            fi
        done
        if [[ -n "$current" ]]; then
            out+="$current"$'\n'
        fi
    done <<<"$text"

    # Remove trailing newline
    out="${out%$'\n'}"
    printf '%s' "$out"
}

# Read a single keypress, handling escape sequences properly
# Sets global variable: CLACK_KEY
__clack_read_key() {
    local key
    CLACK_KEY=""

    # Read first character
    IFS= read -rsn1 key 2>/dev/null </dev/tty

    # Handle escape sequence
    if [[ "$key" == $'\x1b' ]]; then
        local seq=""

        # Try to read up to 3 more characters with timeout
        # Using longer timeout for macOS bash 3.2 compatibility
        if read -rsn1 -t 1 seq 2>/dev/null </dev/tty; then
            if [[ "$seq" == "[" ]]; then
                # CSI sequence: ESC [ ...
                local code=""
                if read -rsn1 -t 1 code 2>/dev/null </dev/tty; then
                    case "$code" in
                        A) CLACK_KEY="UP"; return ;;
                        B) CLACK_KEY="DOWN"; return ;;
                        C) CLACK_KEY="RIGHT"; return ;;
                        D) CLACK_KEY="LEFT"; return ;;
                        H) CLACK_KEY="HOME"; return ;;
                        F) CLACK_KEY="END"; return ;;
                        [0-9])
                            # Extended sequence like ESC [ 1 ~ or ESC [ 1 5 ~
                            local extra=""
                            read -rsn1 -t 1 extra 2>/dev/null </dev/tty
                            case "${code}${extra}" in
                                "1~"|"7~") CLACK_KEY="HOME"; return ;;
                                "4~"|"8~") CLACK_KEY="END"; return ;;
                                "3~") CLACK_KEY="DELETE"; return ;;
                                "5~") CLACK_KEY="PAGEUP"; return ;;
                                "6~") CLACK_KEY="PAGEDOWN"; return ;;
                            esac
                            ;;
                    esac
                fi
            elif [[ "$seq" == "O" ]]; then
                # SS3 sequence: ESC O ...
                local code=""
                if read -rsn1 -t 1 code 2>/dev/null </dev/tty; then
                    case "$code" in
                        A) CLACK_KEY="UP"; return ;;
                        B) CLACK_KEY="DOWN"; return ;;
                        C) CLACK_KEY="RIGHT"; return ;;
                        D) CLACK_KEY="LEFT"; return ;;
                        H) CLACK_KEY="HOME"; return ;;
                        F) CLACK_KEY="END"; return ;;
                    esac
                fi
            fi
        fi

        CLACK_KEY="ESCAPE"
        return
    fi

    # Handle special characters
    if [[ "$key" == "" ]]; then
        CLACK_KEY="ENTER"
    elif [[ "$key" == " " ]]; then
        CLACK_KEY="SPACE"
    elif [[ "$key" == $'\t' ]]; then
        CLACK_KEY="TAB"
    elif [[ "$key" == $'\x7f' ]] || [[ "$key" == $'\b' ]]; then
        CLACK_KEY="BACKSPACE"
    elif [[ "$key" == $'\x03' ]]; then
        # Ctrl+C
        CLACK_KEY="CTRL_C"
    else
        CLACK_KEY="$key"
    fi
}

# ============================================================================
# CANCEL HANDLING
# ============================================================================

CLACK_CANCELLED=0

__clack_handle_cancel() {
    CLACK_CANCELLED=1
    __clack_cursor_show
}

clack_is_cancel() {
    ((CLACK_CANCELLED == 1))
}

# ============================================================================
# INTRO / OUTRO
# ============================================================================

clack_intro() {
    local title="${1:-}"
    __clack_print "${C_GRAY}${S_BAR_START}${C_RESET}  ${title}"
}

clack_outro() {
    local message="${1:-}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GRAY}${S_BAR_END}${C_RESET}  ${message}"
    __clack_print ""
}

clack_cancel() {
    local message="${1:-Operation cancelled.}"
    __clack_print "${C_GRAY}${S_BAR_END}${C_RESET}  ${C_RED}${message}${C_RESET}"
    __clack_print ""
}

# ============================================================================
# LOGGING
# ============================================================================

clack_log_message() {
    local message="${1:-}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${message}"
}

clack_log_info() {
    local message="${1:-}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_BLUE}${S_INFO}${C_RESET}  ${message}"
}

clack_log_success() {
    local message="${1:-}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GREEN}${S_SUCCESS}${C_RESET}  ${message}"
}

clack_log_step() {
    local message="${1:-}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GREEN}${S_STEP_SUBMIT}${C_RESET}  ${message}"
}

clack_log_warn() {
    local message="${1:-}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_YELLOW}${S_WARN}${C_RESET}  ${message}"
}

clack_log_warning() { clack_log_warn "$@"; }

clack_log_error() {
    local message="${1:-}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_RED}${S_ERROR}${C_RESET}  ${message}"
}

# ============================================================================
# TEXT PROMPT
# ============================================================================

clack_text() {
    local message="${1:-Enter text}"
    local placeholder="${2:-}"
    local default_value="${3:-}"
    local validate_fn="${4:-}"
    local input_val=""
    local __interrupted=0
    local error_msg=""
    local first_render=1
    local total_lines=3
    local bash4_plus=0

    # Check if Bash 4+ (supports read -i)
    ((BASH_VERSINFO[0] >= 4)) && bash4_plus=1

    CLACK_CANCELLED=0
    trap '__interrupted=1' INT

    while true; do
        # Clear previous render (except first time)
        if ((first_render == 0)); then
            __clack_clear_lines $total_lines
        fi
        first_render=0

        # Render prompt state
        __clack_print "${C_GRAY}${S_BAR}${C_RESET}"

        if [[ -n "$error_msg" ]]; then
            __clack_print "${C_YELLOW}${S_STEP_ERROR}${C_RESET}  ${message}"
            # Read input with error state
            if ((bash4_plus)); then
                IFS= read -e -r -p "$(printf '%b' "${C_YELLOW}${S_BAR}${C_RESET}  ")" -i "$input_val" input_val </dev/tty 2>&2
            else
                # Bash 3: show current value like npm (first char inverse, rest dim)
                local hint=""
                if [[ -n "$input_val" ]]; then
                    local first_char="${input_val:0:1}"
                    local rest_chars="${input_val:1}"
                    hint="${C_INVERSE}${first_char}${C_RESET}${C_DIM}${rest_chars}${C_RESET} "
                fi
                IFS= read -e -r -p "$(printf '%b' "${C_YELLOW}${S_BAR}${C_RESET}  ${hint}")" input_val </dev/tty 2>&2
            fi
            local status=$?

            if ((status != 0)) || ((__interrupted)); then
                __clack_handle_cancel
                __clack_clear_lines 3
                __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
                __clack_print "${C_RED}${S_STEP_CANCEL}${C_RESET}  ${message}"
                __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${C_DIM}${C_STRIKETHROUGH}${input_val}${C_RESET}"
                trap - INT
                return 1
            fi

            # Show error message
            __clack_print "${C_YELLOW}${S_BAR_END}${C_RESET}  ${C_YELLOW}${error_msg}${C_RESET}"
            total_lines=4
        else
            __clack_print "${C_CYAN}${S_STEP_ACTIVE}${C_RESET}  ${message}"
            # Read input
            local init_val=""
            if [[ -n "$default_value" ]] && [[ -z "$input_val" ]]; then
                init_val="$default_value"
            else
                init_val="$input_val"
            fi

            if ((bash4_plus)); then
                IFS= read -e -r -p "$(printf '%b' "${C_CYAN}${S_BAR}${C_RESET}  ")" -i "$init_val" input_val </dev/tty 2>&2
            else
                # Bash 3: show default/placeholder like npm (first char inverse, rest dim)
                local show_val=""
                if [[ -n "$init_val" ]]; then
                    show_val="$init_val"
                elif [[ -n "$placeholder" ]]; then
                    show_val="$placeholder"
                fi
                if [[ -n "$show_val" ]]; then
                    local first_char="${show_val:0:1}"
                    local rest_chars="${show_val:1}"
                    local hint="${C_INVERSE}${first_char}${C_RESET}${C_DIM}${rest_chars}${C_RESET} "
                    IFS= read -e -r -p "$(printf '%b' "${C_CYAN}${S_BAR}${C_RESET}  ${hint}")" input_val </dev/tty 2>&2
                else
                    IFS= read -e -r -p "$(printf '%b' "${C_CYAN}${S_BAR}${C_RESET}  ")" input_val </dev/tty 2>&2
                fi
                # Use default if empty
                [[ -z "$input_val" ]] && [[ -n "$init_val" ]] && input_val="$init_val"
            fi
            local status=$?

            if ((status != 0)) || ((__interrupted)); then
                __clack_handle_cancel
                __clack_clear_lines 3
                __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
                __clack_print "${C_RED}${S_STEP_CANCEL}${C_RESET}  ${message}"
                __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${C_DIM}${C_STRIKETHROUGH}${input_val}${C_RESET}"
                trap - INT
                return 1
            fi
            total_lines=3
        fi

        # Validate if function provided
        if [[ -n "$validate_fn" ]]; then
            error_msg=$("$validate_fn" "$input_val")
            if [[ -n "$error_msg" ]]; then
                continue
            fi
        fi

        break
    done

    trap - INT

    # Render submit state
    __clack_clear_lines $total_lines
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GREEN}${S_STEP_SUBMIT}${C_RESET}  ${message}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${C_DIM}${input_val}${C_RESET}"

    printf '%s' "$input_val"
}

# ============================================================================
# PASSWORD PROMPT
# ============================================================================

clack_password() {
    local message="${1:-Enter password}"
    local mask="${2:-$S_PASSWORD_MASK}"
    local input_val=""
    local __interrupted=0

    CLACK_CANCELLED=0
    trap '__interrupted=1' INT

    __clack_cursor_hide

    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_CYAN}${S_STEP_ACTIVE}${C_RESET}  ${message}"
    printf '%b' "${C_CYAN}${S_BAR}${C_RESET}  " >&2

    # Read character by character to show real-time masking
    local char
    while true; do
        if ((__interrupted)); then
            break
        fi

        IFS= read -rsn1 char </dev/tty 2>&2

        # Check for Enter (empty char after read -n1)
        if [[ -z "$char" ]]; then
            break
        fi

        # Check for backspace (ASCII 127 or 8)
        if [[ "$char" == $'\x7f' ]] || [[ "$char" == $'\x08' ]]; then
            if ((${#input_val} > 0)); then
                input_val="${input_val%?}"
                # Rebuild masked display
                local masked=""
                local i
                for ((i = 0; i < ${#input_val}; i++)); do masked+="$mask"; done
                printf '\r\033[K%b' "${C_CYAN}${S_BAR}${C_RESET}  ${masked}" >&2
            fi
            continue
        fi

        # Check for Ctrl+C (ASCII 3)
        if [[ "$char" == $'\x03' ]]; then
            __interrupted=1
            break
        fi

        # Add character and show mask
        input_val+="$char"
        printf '%b' "${mask}" >&2
    done

    printf '\n' >&2
    __clack_cursor_show
    trap - INT

    if ((__interrupted)); then
        __clack_handle_cancel
        __clack_clear_lines 3
        __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
        __clack_print "${C_RED}${S_STEP_CANCEL}${C_RESET}  ${message}"
        __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
        return 1
    fi

    local len=${#input_val}
    local masked=""
    local i
    for ((i = 0; i < len; i++)); do masked+="$mask"; done

    __clack_clear_lines 3
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GREEN}${S_STEP_SUBMIT}${C_RESET}  ${message}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${C_DIM}${masked}${C_RESET}"

    printf '%s' "$input_val"
}

# ============================================================================
# CONFIRM PROMPT
# ============================================================================

clack_confirm() {
    local message="${1:-Confirm?}"
    local default_yes="${2:-true}"
    local active_label="${3:-Yes}"
    local inactive_label="${4:-No}"
    local selected=0
    local __interrupted=0

    CLACK_CANCELLED=0

    [[ "$default_yes" == "true" ]] && selected=0 || selected=1

    trap '__interrupted=1' INT
    __clack_cursor_hide

    local total_lines=4

    while true; do
        if ((__interrupted)); then
            __clack_cursor_show
            __clack_handle_cancel
            __clack_clear_lines $total_lines
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
            __clack_print "${C_RED}${S_STEP_CANCEL}${C_RESET}  ${message}"
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
            trap - INT
            return 1
        fi

        __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
        __clack_print "${C_CYAN}${S_STEP_ACTIVE}${C_RESET}  ${message}"

        local yes_str no_str
        if ((selected == 0)); then
            yes_str="${C_GREEN}${S_RADIO_ACTIVE} ${active_label}${C_RESET}"
            no_str="${C_DIM}${S_RADIO_INACTIVE} ${inactive_label}${C_RESET}"
        else
            yes_str="${C_DIM}${S_RADIO_INACTIVE} ${active_label}${C_RESET}"
            no_str="${C_GREEN}${S_RADIO_ACTIVE} ${inactive_label}${C_RESET}"
        fi

        __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${yes_str} ${C_DIM}/${C_RESET} ${no_str}"
        __clack_print "${C_CYAN}${S_BAR_END}${C_RESET}"

        __clack_read_key

        if [[ "$CLACK_KEY" == "CTRL_C" ]]; then
            __interrupted=1
            __clack_clear_lines $total_lines
            continue
        fi

        case "$CLACK_KEY" in
            UP|DOWN|LEFT|RIGHT|TAB)
                selected=$((1 - selected))
                ;;
            y|Y)
                selected=0
                break
                ;;
            n|N)
                selected=1
                break
                ;;
            ENTER|SPACE)
                break
                ;;
        esac

        __clack_clear_lines $total_lines
    done

    __clack_cursor_show
    trap - INT

    local result_text result_bool
    if ((selected == 0)); then
        result_text="$active_label"
        result_bool="true"
    else
        result_text="$inactive_label"
        result_bool="false"
    fi

    __clack_clear_lines $total_lines
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GREEN}${S_STEP_SUBMIT}${C_RESET}  ${message}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${C_DIM}${result_text}${C_RESET}"

    printf '%s' "$result_bool"
    [[ "$result_bool" == "true" ]]
}

# ============================================================================
# SELECT PROMPT
# ============================================================================

clack_select() {
    local message="${1:-Select an option}"
    shift
    local -a options=("$@")
    local count=${#options[@]}
    local cursor=0
    local -a opt_values=()
    local -a opt_labels=()
    local -a opt_hints=()
    local -a opt_disabled=()
    local __interrupted=0

    CLACK_CANCELLED=0

    if ((count == 0)); then
        __clack_print "${C_RED}Error: No options provided${C_RESET}"
        return 1
    fi

    local raw
    for raw in "${options[@]}"; do
        local __parsed __v __l __h __d
        __parsed=$(__clack_parse_option "$raw")
        IFS="$__CLACK_FIELD_SEP" read -r __v __l __h __d <<<"$__parsed"
        opt_values+=("${__v}")
        opt_labels+=("${__l}")
        opt_hints+=("${__h}")
        opt_disabled+=("${__d:-0}")
    done

    if ((opt_disabled[cursor] == 1)); then
        cursor="$(__clack_find_next_enabled opt_disabled "$cursor" 1 "$count")"
    fi

    trap '__interrupted=1' INT
    __clack_cursor_hide

    local total_lines=$((2 + count + 1))

    while true; do
        if ((__interrupted)); then
            __clack_cursor_show
            __clack_handle_cancel
            __clack_clear_lines $total_lines
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
            __clack_print "${C_RED}${S_STEP_CANCEL}${C_RESET}  ${message}"
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
            trap - INT
            return 1
        fi

        __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
        __clack_print "${C_CYAN}${S_STEP_ACTIVE}${C_RESET}  ${message}"

        local i
        for ((i = 0; i < count; i++)); do
            local label="${opt_labels[$i]}"
            local hint="${opt_hints[$i]}"

            if ((opt_disabled[i] == 1)); then
                local hint_text=""
                if [[ -n "$hint" ]]; then
                    hint_text=" ${C_DIM}(${hint})${C_RESET}"
                else
                    hint_text=" ${C_DIM}(disabled)${C_RESET}"
                fi
                __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}${S_RADIO_INACTIVE} ${C_DIM}${label}${C_RESET}${hint_text}"
                continue
            fi

            if ((i == cursor)); then
                if [[ -n "$hint" ]]; then
                    __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_GREEN}${S_RADIO_ACTIVE} ${label} ${C_DIM}(${hint})${C_RESET}"
                else
                    __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_GREEN}${S_RADIO_ACTIVE} ${label}${C_RESET}"
                fi
            else
                __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}${S_RADIO_INACTIVE} ${C_DIM}${label}${C_RESET}"
            fi
        done

        __clack_print "${C_CYAN}${S_BAR_END}${C_RESET}"

        __clack_read_key

        if [[ "$CLACK_KEY" == "CTRL_C" ]]; then
            __interrupted=1
            __clack_clear_lines $total_lines
            continue
        fi

        case "$CLACK_KEY" in
            UP|k|K)
                cursor="$(__clack_find_next_enabled opt_disabled "$cursor" -1 "$count")"
                ;;
            DOWN|j|J)
                cursor="$(__clack_find_next_enabled opt_disabled "$cursor" 1 "$count")"
                ;;
            ENTER)
                if ((opt_disabled[cursor] == 0)); then
                    break
                fi
                ;;
        esac

        __clack_clear_lines $total_lines
    done

    __clack_cursor_show
    trap - INT

    __clack_clear_lines $total_lines
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GREEN}${S_STEP_SUBMIT}${C_RESET}  ${message}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${C_DIM}${opt_labels[$cursor]}${C_RESET}"

    printf '%s' "${opt_values[$cursor]}"
}

# ============================================================================
# MULTI-SELECT PROMPT
# ============================================================================

clack_multiselect() {
    local __result_var=$1
    shift
    local message="${1:-Select options}"
    shift
    local -a options=("$@")
    local count=${#options[@]}
    local cursor=0
    local -a selected_map=()
    local -a opt_values=()
    local -a opt_labels=()
    local -a opt_hints=()
    local -a opt_disabled=()
    local __interrupted=0

    CLACK_CANCELLED=0

    local i
    for ((i = 0; i < count; i++)); do
        selected_map[$i]=0
    done

    if ((count == 0)); then
        __clack_print "${C_RED}Error: No options provided${C_RESET}"
        return 1
    fi

    local raw
    for raw in "${options[@]}"; do
        local __parsed __v __l __h __d
        __parsed=$(__clack_parse_option "$raw")
        IFS="$__CLACK_FIELD_SEP" read -r __v __l __h __d <<<"$__parsed"
        opt_values+=("${__v}")
        opt_labels+=("${__l}")
        opt_hints+=("${__h}")
        opt_disabled+=("${__d:-0}")
    done

    if ((opt_disabled[cursor] == 1)); then
        cursor="$(__clack_find_next_enabled opt_disabled "$cursor" 1 "$count")"
    fi

    trap '__interrupted=1' INT
    __clack_cursor_hide

    local total_lines=$((2 + count + 1))

    while true; do
        if ((__interrupted)); then
            __clack_cursor_show
            __clack_handle_cancel
            __clack_clear_lines $total_lines
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
            __clack_print "${C_RED}${S_STEP_CANCEL}${C_RESET}  ${message}"
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
            trap - INT
            return 1
        fi

        __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
        __clack_print "${C_CYAN}${S_STEP_ACTIVE}${C_RESET}  ${message}"

        for ((i = 0; i < count; i++)); do
            local label="${opt_labels[$i]}"
            local hint="${opt_hints[$i]}"
            local is_selected=${selected_map[$i]}
            local is_cursor=0
            ((i == cursor)) && is_cursor=1

            local icon text_style

            if ((opt_disabled[i] == 1)); then
                icon="${C_DIM}${S_CHECKBOX_INACTIVE}${C_RESET}"
                local hint_text=""
                if [[ -n "$hint" ]]; then
                    hint_text=" ${C_DIM}(${hint})${C_RESET}"
                else
                    hint_text=" ${C_DIM}(disabled)${C_RESET}"
                fi
                text_style="${C_STRIKETHROUGH}${C_DIM}${label}${C_RESET}${hint_text}"
                __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${icon} ${text_style}"
                continue
            fi

            if ((is_selected == 1)); then
                icon="${C_GREEN}${S_CHECKBOX_SELECTED}${C_RESET}"
                if ((is_cursor == 1)); then
                    if [[ -n "$hint" ]]; then
                        text_style="${label} ${C_DIM}(${hint})${C_RESET}"
                    else
                        text_style="${label}"
                    fi
                else
                    text_style="${C_DIM}${label}${C_RESET}"
                fi
            else
                if ((is_cursor == 1)); then
                    icon="${C_CYAN}${S_CHECKBOX_ACTIVE}${C_RESET}"
                    if [[ -n "$hint" ]]; then
                        text_style="${label} ${C_DIM}(${hint})${C_RESET}"
                    else
                        text_style="${label}"
                    fi
                else
                    icon="${C_DIM}${S_CHECKBOX_INACTIVE}${C_RESET}"
                    text_style="${C_DIM}${label}${C_RESET}"
                fi
            fi

            __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${icon} ${text_style}"
        done

        __clack_print "${C_CYAN}${S_BAR_END}${C_RESET}"

        __clack_read_key

        if [[ "$CLACK_KEY" == "CTRL_C" ]]; then
            __interrupted=1
            __clack_clear_lines $total_lines
            continue
        fi

        case "$CLACK_KEY" in
            UP|k|K)
                cursor="$(__clack_find_next_enabled opt_disabled "$cursor" -1 "$count")"
                ;;
            DOWN|j|J)
                cursor="$(__clack_find_next_enabled opt_disabled "$cursor" 1 "$count")"
                ;;
            SPACE)
                if ((opt_disabled[cursor] == 0)); then
                    if ((selected_map[cursor] == 1)); then
                        selected_map[$cursor]=0
                    else
                        selected_map[$cursor]=1
                    fi
                fi
                ;;
            a|A)
                for ((i = 0; i < count; i++)); do
                    if ((opt_disabled[i] == 0)); then
                        selected_map[$i]=1
                    fi
                done
                ;;
            ENTER)
                break
                ;;
        esac

        __clack_clear_lines $total_lines
    done

    __clack_cursor_show
    trap - INT

    # Build result
    eval "${__result_var}=()"
    local -a display_items=()
    for ((i = 0; i < count; i++)); do
        if ((selected_map[i] == 1)); then
            local __q
            printf -v __q '%q' "${opt_values[$i]}"
            eval "${__result_var}+=( ${__q} )"
            display_items+=("${opt_labels[$i]}")
        fi
    done

    local display_text
    if ((${#display_items[@]} == 0)); then
        display_text="${C_DIM}none${C_RESET}"
    else
        display_text="${C_DIM}$(IFS=", "; echo "${display_items[*]}")${C_RESET}"
    fi

    __clack_clear_lines $total_lines
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GREEN}${S_STEP_SUBMIT}${C_RESET}  ${message}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${display_text}"
}

# ============================================================================
# SELECT KEY PROMPT
# ============================================================================

clack_select_key() {
    local message="${1:-Select an option}"
    shift

    local case_sensitive="false"
    if [[ "$#" -gt 0 ]]; then
        case "$1" in
            true|false) case_sensitive="$1"; shift ;;
        esac
    fi

    local -a options=("$@")
    local count=${#options[@]}
    local cursor=0
    local -a opt_values=()
    local -a opt_labels=()
    local -a opt_hints=()
    local -a opt_disabled=()
    local __interrupted=0

    CLACK_CANCELLED=0

    if ((count == 0)); then
        __clack_print "${C_RED}Error: No options provided${C_RESET}"
        return 1
    fi

    local raw
    for raw in "${options[@]}"; do
        local __parsed __v __l __h __d
        __parsed=$(__clack_parse_option "$raw")
        IFS="$__CLACK_FIELD_SEP" read -r __v __l __h __d <<<"$__parsed"
        opt_values+=("${__v}")
        opt_labels+=("${__l}")
        opt_hints+=("${__h}")
        opt_disabled+=("${__d:-0}")
    done

    if ((opt_disabled[cursor] == 1)); then
        cursor="$(__clack_find_next_enabled opt_disabled "$cursor" 1 "$count")"
    fi

    trap '__interrupted=1' INT
    __clack_cursor_hide

    local total_lines=$((2 + count + 1))

    while true; do
        if ((__interrupted)); then
            __clack_cursor_show
            __clack_handle_cancel
            __clack_clear_lines $total_lines
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
            __clack_print "${C_RED}${S_STEP_CANCEL}${C_RESET}  ${message}"
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
            trap - INT
            return 1
        fi

        __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
        __clack_print "${C_CYAN}${S_STEP_ACTIVE}${C_RESET}  ${message}"

        local i
        for ((i = 0; i < count; i++)); do
            local v="${opt_values[$i]}"
            local label="${opt_labels[$i]}"
            local hint="${opt_hints[$i]}"

            local keycap
            if ((i == cursor)); then
                keycap="${C_BG_CYAN}${C_BLACK} ${v} ${C_RESET}"
            else
                keycap="${C_BG_WHITE}${C_BLACK} ${v} ${C_RESET}"
            fi

            if ((opt_disabled[i] == 1)); then
                local hint_text=""
                if [[ -n "$hint" ]]; then
                    hint_text=" ${C_DIM}(${hint})${C_RESET}"
                else
                    hint_text=" ${C_DIM}(disabled)${C_RESET}"
                fi
                __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}${keycap}${C_RESET} ${C_STRIKETHROUGH}${C_DIM}${label}${C_RESET}${hint_text}"
            else
                if [[ -n "$hint" ]]; then
                    __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${keycap} ${label} ${C_DIM}(${hint})${C_RESET}"
                else
                    __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${keycap} ${label}"
                fi
            fi
        done

        __clack_print "${C_CYAN}${S_BAR_END}${C_RESET}"

        __clack_read_key

        if [[ "$CLACK_KEY" == "CTRL_C" ]]; then
            __interrupted=1
            __clack_clear_lines $total_lines
            continue
        fi

        case "$CLACK_KEY" in
            UP|k|K)
                cursor="$(__clack_find_next_enabled opt_disabled "$cursor" -1 "$count")"
                ;;
            DOWN|j|J)
                cursor="$(__clack_find_next_enabled opt_disabled "$cursor" 1 "$count")"
                ;;
            ENTER)
                if ((opt_disabled[cursor] == 0)); then
                    break
                fi
                ;;
            *)
                if ((${#CLACK_KEY} == 1)); then
                    local key_in="$CLACK_KEY"
                    for ((i = 0; i < count; i++)); do
                        if ((opt_disabled[i] == 1)); then
                            continue
                        fi
                        local candidate="${opt_values[$i]}"
                        if [[ "$case_sensitive" == "true" ]]; then
                            if [[ "$candidate" == "$key_in" ]]; then
                                cursor=$i
                                break
                            fi
                        else
                            if [[ "$(__clack_to_lower "$candidate")" == "$(__clack_to_lower "$key_in")" ]]; then
                                cursor=$i
                                break
                            fi
                        fi
                    done
                fi
                ;;
        esac

        __clack_clear_lines $total_lines
    done

    __clack_cursor_show
    trap - INT

    __clack_clear_lines $total_lines
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GREEN}${S_STEP_SUBMIT}${C_RESET}  ${message}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${C_DIM}${opt_labels[$cursor]}${C_RESET}"

    printf '%s' "${opt_values[$cursor]}"
}

# ============================================================================
# BOX
# ============================================================================

clack_box() {
    local message="${1:-}"
    local title="${2:-}"
    local width="${3:-auto}"
    local rounded="${4:-true}"
    local content_align="${5:-left}"
    local title_align="${6:-left}"
    local content_padding="${7:-2}"
    local title_padding="${8:-1}"

    message="${message//\\n/$'\n'}"

    # Get terminal width
    local cols
    cols=$(tput cols 2>/dev/null || printf '80')

    # Calculate usable width (accounting for bar prefix)
    local prefix_len=3  # "│ " plus a space
    local usable=$((cols - prefix_len))
    ((usable < 20)) && usable=20

    # Max inner content width
    local inner_max=$((usable - 2 - (content_padding * 2)))
    ((inner_max < 10)) && inner_max=10

    # Wrap the text
    local wrapped
    wrapped=$(__clack_wrap_text "$inner_max" "$message")

    # Find the longest line
    local max_line=0
    local line
    while IFS= read -r line || [[ -n "$line" ]]; do
        ((${#line} > max_line)) && max_line=${#line}
    done <<<"$wrapped"
    ((${#title} > max_line)) && max_line=${#title}

    # Calculate box dimensions
    local inner_width=$((max_line + (content_padding * 2)))
    local box_width=$((inner_width + 2))

    # Apply manual width if specified
    if [[ "$width" != "auto" ]] && [[ "$width" =~ ^[0-9]+$ ]] && ((width > 0)); then
        if ((width < usable)); then
            box_width=$width
            inner_width=$((box_width - 2))
        fi
    fi

    # Clamp to usable width
    if ((box_width > usable)); then
        box_width=$usable
        inner_width=$((box_width - 2))
    fi

    # Select corner characters
    local tl tr bl br
    if [[ "$rounded" == "true" ]]; then
        tl="$S_CORNER_TOP_LEFT"
        tr="$S_CORNER_TOP_RIGHT"
        bl="$S_CORNER_BOTTOM_LEFT"
        br="$S_CORNER_BOTTOM_RIGHT"
    else
        tl="$S_BAR_START"
        tr="$S_BAR_START_RIGHT"
        bl="$S_BAR_END"
        br="$S_BAR_END_RIGHT"
    fi

    # Build horizontal bar
    local h_bar=""
    local i
    for ((i = 0; i < inner_width; i++)); do
        h_bar+="$S_BAR_H"
    done

    # Build title line
    local title_len=${#title}
    local max_title_len=$((inner_width - 2))
    if ((title_len > max_title_len)); then
        if ((max_title_len > 3)); then
            title="${title:0:$((max_title_len - 3))}..."
        else
            title="${title:0:$max_title_len}"
        fi
        title_len=${#title}
    fi

    local title_fill=$((inner_width - title_len - 2))
    ((title_fill < 0)) && title_fill=0

    local title_bar="$S_BAR_H"
    for ((i = 0; i < title_fill; i++)); do
        title_bar+="$S_BAR_H"
    done

    # Calculate title padding based on alignment
    local title_left_pad="" title_right_pad=""
    local title_available=$((inner_width - title_len))
    case "$title_align" in
        center)
            local title_left_count=$((title_available / 2))
            local title_right_count=$((title_available - title_left_count))
            for ((i = 0; i < title_left_count; i++)); do title_left_pad+="$S_BAR_H"; done
            for ((i = 0; i < title_right_count; i++)); do title_right_pad+="$S_BAR_H"; done
            ;;
        right)
            for ((i = 0; i < title_available - title_padding; i++)); do title_left_pad+="$S_BAR_H"; done
            for ((i = 0; i < title_padding; i++)); do title_right_pad+="$S_BAR_H"; done
            ;;
        *)  # left
            for ((i = 0; i < title_padding; i++)); do title_left_pad+="$S_BAR_H"; done
            for ((i = 0; i < title_available - title_padding; i++)); do title_right_pad+="$S_BAR_H"; done
            ;;
    esac

    # Print empty bar line
    printf '%s\n' "${C_GRAY}${S_BAR}${C_RESET}" >&2

    # Print top border with title
    printf '%s\n' "${C_GRAY}${S_BAR}${C_RESET} ${C_GRAY}${tl}${title_left_pad}${title}${title_right_pad}${tr}${C_RESET}" >&2

    # Print wrapped content lines
    while IFS= read -r line || [[ -n "$line" ]]; do
        local line_len=${#line}
        local total_pad=$((inner_width - line_len))
        local left_pad_count right_pad_count

        case "$content_align" in
            center)
                left_pad_count=$((total_pad / 2))
                right_pad_count=$((total_pad - left_pad_count))
                ;;
            right)
                left_pad_count=$((total_pad - content_padding))
                right_pad_count=$content_padding
                ;;
            *)  # left
                left_pad_count=$content_padding
                right_pad_count=$((total_pad - content_padding))
                ;;
        esac

        local left_pad="" right_pad=""
        for ((i = 0; i < left_pad_count; i++)); do left_pad+=" "; done
        for ((i = 0; i < right_pad_count; i++)); do right_pad+=" "; done

        printf '%s\n' "${C_GRAY}${S_BAR}${C_RESET} ${C_GRAY}${S_BAR}${C_RESET}${left_pad}${line}${right_pad}${C_GRAY}${S_BAR}${C_RESET}" >&2
    done <<<"$wrapped"

    # Print bottom border
    printf '%s\n' "${C_GRAY}${S_BAR}${C_RESET} ${C_GRAY}${bl}${h_bar}${br}${C_RESET}" >&2
}

# ============================================================================
# SPINNER
# ============================================================================
# Options:
#   clack_spinner_start "Message" [indicator]
#   indicator: "dots" (default) or "timer"

__CLACK_SPINNER_PID=""
__CLACK_SPINNER_MSG=""
__CLACK_SPINNER_INDICATOR="dots"
__CLACK_SPINNER_START_TIME=0

__clack_spinner_remove_trailing_dots() {
    local s="$1"
    while [[ "$s" == *"." ]]; do
        s="${s%.}"
    done
    printf '%s' "$s"
}

__clack_spinner_format_timer() {
    local start_time=$1
    local now
    now=$(date +%s)
    local duration=$((now - start_time))
    local min=$((duration / 60))
    local secs=$((duration % 60))
    if ((min > 0)); then
        printf '[%dm %ds]' "$min" "$secs"
    else
        printf '[%ds]' "$secs"
    fi
}

__clack_spinner_loop() {
    local -a frames=("${S_SPINNER_FRAMES[@]}")
    local frame_count=${#frames[@]}
    local i=0
    local dots=0
    local indicator_counter=0
    local delay="0.08"

    if ((CLACK_UNICODE != 1)); then
        delay="0.12"
    fi

    while true; do
        local frame="${frames[$i]}"
        local suffix=""

        if [[ "$__CLACK_SPINNER_INDICATOR" == "timer" ]]; then
            suffix=" $(__clack_spinner_format_timer "$__CLACK_SPINNER_START_TIME")"
        else
            # dots indicator - each dot level lasts 8 frames (matching TypeScript)
            local d
            for ((d = 0; d < dots; d++)); do suffix+="."; done
        fi

        printf '\r\033[K%b' "${C_MAGENTA}${frame}${C_RESET}  ${__CLACK_SPINNER_MSG}${suffix}   " >&2

        sleep "$delay"

        i=$(((i + 1) % frame_count))

        # Increment dots every 8 frames (TypeScript: indicatorTimer += 0.125, so 8 frames per dot)
        indicator_counter=$((indicator_counter + 1))
        if ((indicator_counter >= 8)); then
            indicator_counter=0
            dots=$(((dots + 1) % 4))
        fi
    done
}

clack_spinner_start() {
    local msg="${1:-Loading}"
    local indicator="${2:-dots}"
    __CLACK_SPINNER_MSG="$(__clack_spinner_remove_trailing_dots "$msg")"
    __CLACK_SPINNER_INDICATOR="$indicator"
    __CLACK_SPINNER_START_TIME=$(date +%s)

    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"

    __clack_spinner_loop &
    __CLACK_SPINNER_PID=$!
    disown "$__CLACK_SPINNER_PID" 2>/dev/null
}

clack_spinner_stop() {
    local msg="${1:-Done}"
    local timer_suffix=""

    if [[ -n "$__CLACK_SPINNER_PID" ]]; then
        kill "$__CLACK_SPINNER_PID" 2>/dev/null
        wait "$__CLACK_SPINNER_PID" 2>/dev/null
        __CLACK_SPINNER_PID=""
    fi

    if [[ "$__CLACK_SPINNER_INDICATOR" == "timer" ]]; then
        timer_suffix=" $(__clack_spinner_format_timer "$__CLACK_SPINNER_START_TIME")"
    fi

    printf '\r\033[K' >&2
    __clack_print "${C_GREEN}${S_STEP_SUBMIT}${C_RESET}  ${msg}${timer_suffix}"
}

clack_spinner_error() {
    local msg="${1:-Error}"
    local timer_suffix=""

    if [[ -n "$__CLACK_SPINNER_PID" ]]; then
        kill "$__CLACK_SPINNER_PID" 2>/dev/null
        wait "$__CLACK_SPINNER_PID" 2>/dev/null
        __CLACK_SPINNER_PID=""
    fi

    if [[ "$__CLACK_SPINNER_INDICATOR" == "timer" ]]; then
        timer_suffix=" $(__clack_spinner_format_timer "$__CLACK_SPINNER_START_TIME")"
    fi

    printf '\r\033[K' >&2
    __clack_print "${C_RED}${S_STEP_ERROR}${C_RESET}  ${msg}${timer_suffix}"
}

clack_spinner_cancel() {
    local msg="${1:-Cancelled}"
    local timer_suffix=""

    if [[ -n "$__CLACK_SPINNER_PID" ]]; then
        kill "$__CLACK_SPINNER_PID" 2>/dev/null
        wait "$__CLACK_SPINNER_PID" 2>/dev/null
        __CLACK_SPINNER_PID=""
    fi

    if [[ "$__CLACK_SPINNER_INDICATOR" == "timer" ]]; then
        timer_suffix=" $(__clack_spinner_format_timer "$__CLACK_SPINNER_START_TIME")"
    fi

    printf '\r\033[K' >&2
    __clack_print "${C_RED}${S_STEP_CANCEL}${C_RESET}  ${msg}${timer_suffix}"
}

clack_spinner_message() {
    local msg="${1:-$__CLACK_SPINNER_MSG}"
    __CLACK_SPINNER_MSG="$(__clack_spinner_remove_trailing_dots "$msg")"
}

# ============================================================================
# NOTE
# ============================================================================

clack_note() {
    local title="${1:-}"
    shift
    local -a lines=("$@")

    local cols
    cols=$(tput cols 2>/dev/null || printf '80')
    local wrap_width=$((cols - 6))
    ((wrap_width < 4)) && wrap_width=4

    local -a wrapped_lines=("")
    local line sub wrapped wline
    for line in "${lines[@]}"; do
        line="${line//\\n/$'\n'}"
        while IFS= read -r sub || [[ -n "$sub" ]]; do
            if [[ -z "$sub" ]]; then
                wrapped_lines+=("")
                continue
            fi
            wrapped=$(__clack_wrap_text "$wrap_width" "$sub")
            while IFS= read -r wline || [[ -n "$wline" ]]; do
                wrapped_lines+=("$wline")
            done <<<"$wrapped"
        done <<<"$line"
    done
    wrapped_lines+=("")

    local title_len=${#title}
    local max_width=0
    for line in "${wrapped_lines[@]}"; do
        ((${#line} > max_width)) && max_width=${#line}
    done
    ((title_len > max_width)) && max_width=$title_len

    local len=$((max_width + 2))
    local bar_len=$((len - title_len - 1))
    ((bar_len < 1)) && bar_len=1

    local h_line=""
    local i
    for ((i = 0; i < len + 2; i++)); do h_line+="${S_BAR_H}"; done

    local title_bar=""
    for ((i = 0; i < bar_len; i++)); do title_bar+="${S_BAR_H}"; done

    printf '%s\n' "${C_GRAY}${S_BAR}${C_RESET}" >&2
    printf '%s\n' "${C_GREEN}${S_STEP_SUBMIT}${C_RESET}  ${title} ${C_GRAY}${title_bar}${S_CORNER_TOP_RIGHT}${C_RESET}" >&2

    for line in "${wrapped_lines[@]}"; do
        local padding=$((len - ${#line}))
        ((padding < 0)) && padding=0
        local pad_str=""
        for ((i = 0; i < padding; i++)); do pad_str+=" "; done
        printf '%s\n' "${C_GRAY}${S_BAR}${C_RESET}  ${C_DIM}${line}${C_RESET}${pad_str}${C_GRAY}${S_BAR}${C_RESET}" >&2
    done

    printf '%s\n' "${C_GRAY}${S_CONNECT_LEFT}${h_line}${S_CORNER_BOTTOM_RIGHT}${C_RESET}" >&2
}

# ============================================================================
# TASKS
# ============================================================================

clack_task() {
    local title="$1"
    local command="$2"

    clack_spinner_start "$title"

    if eval "$command" > /dev/null 2>&1; then
        clack_spinner_stop "$title"
        return 0
    else
        clack_spinner_error "$title (failed)"
        return 1
    fi
}

clack_tasks() {
    local __tasks_var=$1
    local __count=0
    eval "__count=\${#${__tasks_var}[@]}"

    local i
    for ((i = 0; i < __count; i++)); do
        local task_def=""
        eval "task_def=\${${__tasks_var}[$i]}"
        local title="${task_def%%:*}"
        local cmd="${task_def#*:}"
        clack_task "$title" "$cmd"
    done
}

# ============================================================================
# PROGRESS BAR
# ============================================================================
# Style options: "light" (─), "heavy" (━), "block" (█)
# Uses spinner animation like TypeScript @clack/prompts
# Usage:
#   clack_progress_start "Message" [max] [size] [style]
#   clack_progress_advance [step] [message]
#   clack_progress_message "New message"
#   clack_progress_stop "Done"
#   clack_progress_cancel "Cancelled"
#   clack_progress_error "Failed"
#   clack_progress_clear

__CLACK_PROGRESS_VALUE=0
__CLACK_PROGRESS_MAX=100
__CLACK_PROGRESS_SIZE=40
__CLACK_PROGRESS_MSG=""
__CLACK_PROGRESS_STYLE="heavy"
__CLACK_PROGRESS_ACTIVE=0
__CLACK_PROGRESS_PID=""
__CLACK_PROGRESS_STATE_FILE=""

# Progress bar characters for each style
if ((CLACK_UNICODE == 1)); then
    __CLACK_PROGRESS_CHAR_LIGHT="─"
    __CLACK_PROGRESS_CHAR_HEAVY="━"
    __CLACK_PROGRESS_CHAR_BLOCK="█"
else
    __CLACK_PROGRESS_CHAR_LIGHT="-"
    __CLACK_PROGRESS_CHAR_HEAVY="="
    __CLACK_PROGRESS_CHAR_BLOCK="#"
fi

__clack_progress_get_char_for_style() {
    local style="$1"
    case "$style" in
        light)
            if ((CLACK_UNICODE == 1)); then printf '%s' "─"; else printf '%s' "-"; fi
            ;;
        block)
            if ((CLACK_UNICODE == 1)); then printf '%s' "█"; else printf '%s' "#"; fi
            ;;
        *)
            if ((CLACK_UNICODE == 1)); then printf '%s' "━"; else printf '%s' "="; fi
            ;;
    esac
}

__clack_progress_loop() {
    local state_file="$1"
    local -a frames=("${S_SPINNER_FRAMES[@]}")
    local frame_count=${#frames[@]}
    local frame_idx=0
    local dots=0
    local indicator_counter=0
    local delay="0.08"

    if ((CLACK_UNICODE != 1)); then
        delay="0.12"
    fi

    while [[ -f "$state_file" ]]; do
        # Read state from file
        local value=0 max=100 size=40 msg="" style="heavy"
        if [[ -f "$state_file" ]]; then
            IFS='|' read -r value max size style msg < "$state_file" 2>/dev/null || true
        fi

        local frame="${frames[$frame_idx]}"
        local dot_str=""
        local d
        for ((d = 0; d < dots; d++)); do dot_str+="."; done

        # Build bar
        local char
        char=$(__clack_progress_get_char_for_style "$style")
        local active=$(( (value * size) / max ))
        local inactive=$(( size - active ))
        local bar=""
        local j
        for ((j = 0; j < active; j++)); do bar+="${C_MAGENTA}${char}${C_RESET}"; done
        for ((j = 0; j < inactive; j++)); do bar+="${C_DIM}${char}${C_RESET}"; done

        printf '\r\033[K%b' "${C_MAGENTA}${frame}${C_RESET}  ${bar} ${msg}${dot_str}   " >&2

        sleep "$delay"

        frame_idx=$(((frame_idx + 1) % frame_count))

        # Increment dots every 8 frames (matching TypeScript timing)
        indicator_counter=$((indicator_counter + 1))
        if ((indicator_counter >= 8)); then
            indicator_counter=0
            dots=$(((dots + 1) % 4))
        fi
    done
}

__clack_progress_write_state() {
    if [[ -n "$__CLACK_PROGRESS_STATE_FILE" ]]; then
        printf '%s|%s|%s|%s|%s' \
            "$__CLACK_PROGRESS_VALUE" \
            "$__CLACK_PROGRESS_MAX" \
            "$__CLACK_PROGRESS_SIZE" \
            "$__CLACK_PROGRESS_STYLE" \
            "$__CLACK_PROGRESS_MSG" > "$__CLACK_PROGRESS_STATE_FILE"
    fi
}

clack_progress_start() {
    local msg="${1:-}"
    local max="${2:-100}"
    local size="${3:-40}"
    local style="${4:-heavy}"

    __CLACK_PROGRESS_VALUE=0
    __CLACK_PROGRESS_MAX=$((max > 0 ? max : 1))
    __CLACK_PROGRESS_SIZE=$((size > 0 ? size : 1))
    __CLACK_PROGRESS_MSG="$msg"
    __CLACK_PROGRESS_STYLE="$style"
    __CLACK_PROGRESS_ACTIVE=1

    # Create temp file for state sharing
    __CLACK_PROGRESS_STATE_FILE=$(mktemp)
    __clack_progress_write_state

    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"

    __clack_progress_loop "$__CLACK_PROGRESS_STATE_FILE" &
    __CLACK_PROGRESS_PID=$!
    disown "$__CLACK_PROGRESS_PID" 2>/dev/null
}

clack_progress_advance() {
    local step="${1:-1}"
    local msg="${2:-$__CLACK_PROGRESS_MSG}"

    __CLACK_PROGRESS_VALUE=$(( __CLACK_PROGRESS_VALUE + step ))
    ((__CLACK_PROGRESS_VALUE > __CLACK_PROGRESS_MAX)) && __CLACK_PROGRESS_VALUE=$__CLACK_PROGRESS_MAX
    __CLACK_PROGRESS_MSG="$msg"

    __clack_progress_write_state
}

clack_progress_message() {
    local msg="${1:-$__CLACK_PROGRESS_MSG}"
    __CLACK_PROGRESS_MSG="$msg"
    __clack_progress_write_state
}

__clack_progress_stop_loop() {
    # Remove state file to signal loop to stop
    if [[ -n "$__CLACK_PROGRESS_STATE_FILE" ]] && [[ -f "$__CLACK_PROGRESS_STATE_FILE" ]]; then
        rm -f "$__CLACK_PROGRESS_STATE_FILE"
        __CLACK_PROGRESS_STATE_FILE=""
    fi

    if [[ -n "$__CLACK_PROGRESS_PID" ]]; then
        kill "$__CLACK_PROGRESS_PID" 2>/dev/null
        wait "$__CLACK_PROGRESS_PID" 2>/dev/null
        __CLACK_PROGRESS_PID=""
    fi
}

clack_progress_stop() {
    local msg="${1:-Done}"
    ((__CLACK_PROGRESS_ACTIVE == 0)) && return
    __CLACK_PROGRESS_ACTIVE=0
    __clack_progress_stop_loop
    printf '\r\033[K' >&2
    __clack_print "${C_GREEN}${S_STEP_SUBMIT}${C_RESET}  ${msg}"
}

clack_progress_cancel() {
    local msg="${1:-Cancelled}"
    ((__CLACK_PROGRESS_ACTIVE == 0)) && return
    __CLACK_PROGRESS_ACTIVE=0
    __clack_progress_stop_loop
    printf '\r\033[K' >&2
    __clack_print "${C_RED}${S_STEP_CANCEL}${C_RESET}  ${msg}"
}

clack_progress_error() {
    local msg="${1:-Error}"
    ((__CLACK_PROGRESS_ACTIVE == 0)) && return
    __CLACK_PROGRESS_ACTIVE=0
    __clack_progress_stop_loop
    printf '\r\033[K' >&2
    __clack_print "${C_RED}${S_STEP_ERROR}${C_RESET}  ${msg}"
}

clack_progress_clear() {
    ((__CLACK_PROGRESS_ACTIVE == 0)) && return
    __CLACK_PROGRESS_ACTIVE=0
    __clack_progress_stop_loop
    printf '\r\033[K' >&2
}

# ============================================================================
# LIMIT OPTIONS (Internal helper for pagination)
# ============================================================================

__clack_limit_options() {
    local __result_var=$1
    local cursor=$2
    local max_items=$3
    shift 3
    local -a options=("$@")
    local count=${#options[@]}

    # Get terminal rows
    local rows
    rows=$(tput lines 2>/dev/null || printf '24')

    # Calculate effective max items
    local effective_max=$max_items
    if ((max_items <= 0 || max_items > rows - 6)); then
        effective_max=$((rows - 6))
    fi
    ((effective_max < 5)) && effective_max=5

    # If we can show all options, no pagination needed
    if ((count <= effective_max)); then
        eval "${__result_var}_start=0"
        eval "${__result_var}_end=${count}"
        eval "${__result_var}_top_ellipsis=0"
        eval "${__result_var}_bottom_ellipsis=0"
        return
    fi

    # Calculate sliding window
    local start=0
    if ((cursor >= effective_max - 2)); then
        start=$((cursor - effective_max + 3))
        if ((start > count - effective_max)); then
            start=$((count - effective_max))
        fi
        ((start < 0)) && start=0
    fi

    local end=$((start + effective_max))
    ((end > count)) && end=$count

    local top_ellipsis=0
    local bottom_ellipsis=0

    if ((start > 0)); then
        top_ellipsis=1
        start=$((start + 1))
    fi
    if ((end < count)); then
        bottom_ellipsis=1
        end=$((end - 1))
    fi

    eval "${__result_var}_start=${start}"
    eval "${__result_var}_end=${end}"
    eval "${__result_var}_top_ellipsis=${top_ellipsis}"
    eval "${__result_var}_bottom_ellipsis=${bottom_ellipsis}"
}

# ============================================================================
# GROUP (Run prompts in sequence, collecting results)
# ============================================================================

# Usage:
#   clack_group_start
#   name=$(clack_text "Name?")
#   clack_group_set "name" "$name"
#   if clack_is_cancel; then clack_group_cancel; return 1; fi
#   email=$(clack_text "Email?")
#   clack_group_set "email" "$email"
#   if clack_is_cancel; then clack_group_cancel; return 1; fi
#   clack_group_end RESULT_ARRAY  # Results in RESULT_ARRAY_name, RESULT_ARRAY_email

__CLACK_GROUP_KEYS=()
__CLACK_GROUP_VALUES=()
__CLACK_GROUP_ACTIVE=0

clack_group_start() {
    __CLACK_GROUP_KEYS=()
    __CLACK_GROUP_VALUES=()
    __CLACK_GROUP_ACTIVE=1
}

clack_group_set() {
    local key="$1"
    local value="$2"
    __CLACK_GROUP_KEYS+=("$key")
    __CLACK_GROUP_VALUES+=("$value")
}

clack_group_cancel() {
    __CLACK_GROUP_ACTIVE=0
    clack_cancel "Operation cancelled."
}

clack_group_end() {
    local __prefix="${1:-CLACK_GROUP_RESULT}"
    local i
    for ((i = 0; i < ${#__CLACK_GROUP_KEYS[@]}; i++)); do
        local key="${__CLACK_GROUP_KEYS[$i]}"
        local value="${__CLACK_GROUP_VALUES[$i]}"
        local __q
        printf -v __q '%q' "$value"
        eval "${__prefix}_${key}=${__q}"
    done
    __CLACK_GROUP_ACTIVE=0
}

clack_group_get() {
    local __prefix="${1:-CLACK_GROUP_RESULT}"
    local key="$2"
    local varname="${__prefix}_${key}"
    eval "printf '%s' \"\${${varname}}\""
}

# ============================================================================
# GROUP MULTI-SELECT (Multi-select with grouped options)
# ============================================================================

# Options format: "group:Group Name" for group headers, "value|label|hint" for items
# Example:
#   clack_group_multiselect RESULT "Select features" \
#       "group:Frontend" "react|React|UI library" "vue|Vue|Progressive framework" \
#       "group:Backend" "node|Node.js" "python|Python"

clack_group_multiselect() {
    local __result_var=$1
    shift
    local message="${1:-Select options}"
    shift
    local -a raw_options=("$@")
    local count=${#raw_options[@]}
    local cursor=0
    local -a flat_values=()
    local -a flat_labels=()
    local -a flat_hints=()
    local -a flat_disabled=()
    local -a flat_is_group=()
    local -a flat_group_name=()
    local -a selected_map=()
    local __interrupted=0

    CLACK_CANCELLED=0

    if ((count == 0)); then
        __clack_print "${C_RED}Error: No options provided${C_RESET}"
        return 1
    fi

    # Parse options into flat structure
    local current_group=""
    local raw idx=0
    for raw in "${raw_options[@]}"; do
        if [[ "$raw" == group:* ]]; then
            current_group="${raw#group:}"
            flat_values+=("__group_${current_group}")
            flat_labels+=("$current_group")
            flat_hints+=("")
            flat_disabled+=(0)
            flat_is_group+=(1)
            flat_group_name+=("$current_group")
            selected_map+=(0)
        else
            local __parsed __v __l __h __d
            __parsed=$(__clack_parse_option "$raw")
            IFS="$__CLACK_FIELD_SEP" read -r __v __l __h __d <<<"$__parsed"
            flat_values+=("${__v}")
            flat_labels+=("${__l}")
            flat_hints+=("${__h}")
            flat_disabled+=("${__d:-0}")
            flat_is_group+=(0)
            flat_group_name+=("$current_group")
            selected_map+=(0)
        fi
        ((idx++))
    done

    local total=${#flat_values[@]}

    # Find first non-disabled, non-group item
    for ((cursor = 0; cursor < total; cursor++)); do
        if ((flat_is_group[cursor] == 0 && flat_disabled[cursor] == 0)); then
            break
        fi
    done

    trap '__interrupted=1' INT
    __clack_cursor_hide

    local total_lines=$((2 + total + 1))

    while true; do
        if ((__interrupted)); then
            __clack_cursor_show
            __clack_handle_cancel
            __clack_clear_lines $total_lines
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
            __clack_print "${C_RED}${S_STEP_CANCEL}${C_RESET}  ${message}"
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
            trap - INT
            return 1
        fi

        __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
        __clack_print "${C_CYAN}${S_STEP_ACTIVE}${C_RESET}  ${message}"

        local i
        for ((i = 0; i < total; i++)); do
            local label="${flat_labels[$i]}"
            local hint="${flat_hints[$i]}"
            local is_selected=${selected_map[$i]}
            local is_cursor=0
            ((i == cursor)) && is_cursor=1
            local is_group=${flat_is_group[$i]}

            if ((is_group == 1)); then
                # Group header
                local group_selected=1
                local j
                for ((j = i + 1; j < total; j++)); do
                    if ((flat_is_group[j] == 1)); then
                        break
                    fi
                    if ((flat_disabled[j] == 0 && selected_map[j] == 0)); then
                        group_selected=0
                        break
                    fi
                done

                local icon
                if ((group_selected == 1)); then
                    icon="${C_GREEN}${S_CHECKBOX_SELECTED}${C_RESET}"
                elif ((is_cursor == 1)); then
                    icon="${C_CYAN}${S_CHECKBOX_ACTIVE}${C_RESET}"
                else
                    icon="${C_DIM}${S_CHECKBOX_INACTIVE}${C_RESET}"
                fi

                if ((is_cursor == 1)); then
                    __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${icon} ${label}"
                else
                    __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${icon} ${C_DIM}${label}${C_RESET}"
                fi
            elif ((flat_disabled[i] == 1)); then
                # Disabled item
                local prefix="${C_GRAY}${S_BAR}${C_RESET} "
                local hint_text=""
                if [[ -n "$hint" ]]; then
                    hint_text=" ${C_DIM}(${hint})${C_RESET}"
                else
                    hint_text=" ${C_DIM}(disabled)${C_RESET}"
                fi
                __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${prefix}${C_DIM}${S_CHECKBOX_INACTIVE}${C_RESET} ${C_STRIKETHROUGH}${C_DIM}${label}${C_RESET}${hint_text}"
            else
                # Regular item
                local prefix="${C_GRAY}${S_BAR}${C_RESET} "
                local icon text_style

                if ((is_selected == 1)); then
                    icon="${C_GREEN}${S_CHECKBOX_SELECTED}${C_RESET}"
                    if ((is_cursor == 1)); then
                        if [[ -n "$hint" ]]; then
                            text_style="${label} ${C_DIM}(${hint})${C_RESET}"
                        else
                            text_style="${label}"
                        fi
                    else
                        text_style="${C_DIM}${label}${C_RESET}"
                    fi
                else
                    if ((is_cursor == 1)); then
                        icon="${C_CYAN}${S_CHECKBOX_ACTIVE}${C_RESET}"
                        if [[ -n "$hint" ]]; then
                            text_style="${label} ${C_DIM}(${hint})${C_RESET}"
                        else
                            text_style="${label}"
                        fi
                    else
                        icon="${C_DIM}${S_CHECKBOX_INACTIVE}${C_RESET}"
                        text_style="${C_DIM}${label}${C_RESET}"
                    fi
                fi

                __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${prefix}${icon} ${text_style}"
            fi
        done

        __clack_print "${C_CYAN}${S_BAR_END}${C_RESET}"

        __clack_read_key

        if [[ "$CLACK_KEY" == "CTRL_C" ]]; then
            __interrupted=1
            __clack_clear_lines $total_lines
            continue
        fi

        case "$CLACK_KEY" in
            UP|k|K)
                local found=0
                local try=$cursor
                while ((found == 0)); do
                    ((try--))
                    ((try < 0)) && try=$((total - 1))
                    if ((try == cursor)); then break; fi
                    if ((flat_disabled[try] == 0)); then
                        cursor=$try
                        found=1
                    fi
                done
                ;;
            DOWN|j|J)
                local found=0
                local try=$cursor
                while ((found == 0)); do
                    ((try++))
                    ((try >= total)) && try=0
                    if ((try == cursor)); then break; fi
                    if ((flat_disabled[try] == 0)); then
                        cursor=$try
                        found=1
                    fi
                done
                ;;
            SPACE)
                if ((flat_is_group[cursor] == 1)); then
                    # Toggle all items in group
                    local group_name="${flat_group_name[$cursor]}"
                    local all_selected=1
                    local j
                    for ((j = cursor + 1; j < total; j++)); do
                        if ((flat_is_group[j] == 1)); then
                            break
                        fi
                        if ((flat_disabled[j] == 0 && selected_map[j] == 0)); then
                            all_selected=0
                            break
                        fi
                    done
                    local new_val=$((1 - all_selected))
                    for ((j = cursor + 1; j < total; j++)); do
                        if ((flat_is_group[j] == 1)); then
                            break
                        fi
                        if ((flat_disabled[j] == 0)); then
                            selected_map[$j]=$new_val
                        fi
                    done
                elif ((flat_disabled[cursor] == 0)); then
                    if ((selected_map[cursor] == 1)); then
                        selected_map[$cursor]=0
                    else
                        selected_map[$cursor]=1
                    fi
                fi
                ;;
            a|A)
                # Select all
                for ((i = 0; i < total; i++)); do
                    if ((flat_is_group[i] == 0 && flat_disabled[i] == 0)); then
                        selected_map[$i]=1
                    fi
                done
                ;;
            ENTER)
                break
                ;;
        esac

        __clack_clear_lines $total_lines
    done

    __clack_cursor_show
    trap - INT

    # Build result
    eval "${__result_var}=()"
    local -a display_items=()
    for ((i = 0; i < total; i++)); do
        if ((flat_is_group[i] == 0 && selected_map[i] == 1)); then
            local __q
            printf -v __q '%q' "${flat_values[$i]}"
            eval "${__result_var}+=( ${__q} )"
            display_items+=("${flat_labels[$i]}")
        fi
    done

    local display_text
    if ((${#display_items[@]} == 0)); then
        display_text="${C_DIM}none${C_RESET}"
    else
        display_text="${C_DIM}$(IFS=", "; echo "${display_items[*]}")${C_RESET}"
    fi

    __clack_clear_lines $total_lines
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GREEN}${S_STEP_SUBMIT}${C_RESET}  ${message}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${display_text}"
}

# ============================================================================
# AUTOCOMPLETE (Text input with suggestions/filtering)
# ============================================================================

clack_autocomplete() {
    local message="${1:-Search}"
    shift
    local -a options=("$@")
    local count=${#options[@]}
    local input_val=""
    local cursor=0
    local -a opt_values=()
    local -a opt_labels=()
    local -a opt_hints=()
    local -a filtered_indices=()
    local __interrupted=0
    local is_navigating=0

    CLACK_CANCELLED=0

    if ((count == 0)); then
        __clack_print "${C_RED}Error: No options provided${C_RESET}"
        return 1
    fi

    # Parse options
    local raw
    for raw in "${options[@]}"; do
        local __parsed __v __l __h __d
        __parsed=$(__clack_parse_option "$raw")
        IFS="$__CLACK_FIELD_SEP" read -r __v __l __h __d <<<"$__parsed"
        opt_values+=("${__v}")
        opt_labels+=("${__l}")
        opt_hints+=("${__h}")
    done

    # Initialize filtered indices (all options)
    local i
    for ((i = 0; i < count; i++)); do
        filtered_indices+=($i)
    done

    __clack_filter_options() {
        filtered_indices=()
        local search_lower
        search_lower=$(__clack_to_lower "$input_val")

        for ((i = 0; i < count; i++)); do
            if [[ -z "$input_val" ]]; then
                filtered_indices+=($i)
            else
                local label_lower value_lower hint_lower
                label_lower=$(__clack_to_lower "${opt_labels[$i]}")
                value_lower=$(__clack_to_lower "${opt_values[$i]}")
                hint_lower=$(__clack_to_lower "${opt_hints[$i]}")

                if [[ "$label_lower" == *"$search_lower"* ]] || \
                   [[ "$value_lower" == *"$search_lower"* ]] || \
                   [[ "$hint_lower" == *"$search_lower"* ]]; then
                    filtered_indices+=($i)
                fi
            fi
        done

        # Reset cursor if out of bounds
        if ((cursor >= ${#filtered_indices[@]})); then
            cursor=0
        fi
    }

    trap '__interrupted=1' INT
    __clack_cursor_hide

    local max_display=8

    while true; do
        local filtered_count=${#filtered_indices[@]}
        local display_count=$filtered_count
        ((display_count > max_display)) && display_count=$max_display
        local total_lines=$((5 + display_count + 1))

        if ((__interrupted)); then
            __clack_cursor_show
            __clack_handle_cancel
            __clack_clear_lines $total_lines
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
            __clack_print "${C_RED}${S_STEP_CANCEL}${C_RESET}  ${message}"
            if [[ -n "$input_val" ]]; then
                __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${C_DIM}${C_STRIKETHROUGH}${input_val}${C_RESET}"
            else
                __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
            fi
            trap - INT
            return 1
        fi

        __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
        __clack_print "${C_CYAN}${S_STEP_ACTIVE}${C_RESET}  ${message}"
        __clack_print "${C_CYAN}${S_BAR}${C_RESET}"

        # Search input line
        local search_display
        if ((is_navigating == 1)) && [[ -n "$input_val" ]]; then
            search_display="${C_DIM}${input_val}${C_RESET}"
        elif [[ -n "$input_val" ]]; then
            search_display="${input_val}${C_INVERSE} ${C_RESET}"
        else
            search_display="${C_INVERSE} ${C_RESET}"
        fi

        local match_info=""
        if [[ -n "$input_val" ]] && ((filtered_count != count)); then
            match_info=" ${C_DIM}(${filtered_count} match"
            ((filtered_count != 1)) && match_info+="es"
            match_info+=")${C_RESET}"
        fi

        __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}Search:${C_RESET} ${search_display}${match_info}"

        if ((filtered_count == 0)) && [[ -n "$input_val" ]]; then
            __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_YELLOW}No matches found${C_RESET}"
        else
            # Calculate pagination
            local start=0
            if ((cursor >= max_display - 2)) && ((filtered_count > max_display)); then
                start=$((cursor - max_display + 3))
                ((start > filtered_count - max_display)) && start=$((filtered_count - max_display))
                ((start < 0)) && start=0
            fi
            local end=$((start + max_display))
            ((end > filtered_count)) && end=$filtered_count

            local show_top_ellipsis=0
            local show_bottom_ellipsis=0
            if ((start > 0)); then
                show_top_ellipsis=1
            fi
            if ((end < filtered_count)); then
                show_bottom_ellipsis=1
            fi

            if ((show_top_ellipsis == 1)); then
                __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}...${C_RESET}"
                ((start++))
            fi

            for ((i = start; i < end - show_bottom_ellipsis; i++)); do
                local idx=${filtered_indices[$i]}
                local label="${opt_labels[$idx]}"
                local hint="${opt_hints[$idx]}"

                if ((i == cursor)); then
                    if [[ -n "$hint" ]]; then
                        __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_GREEN}${S_RADIO_ACTIVE} ${label} ${C_DIM}(${hint})${C_RESET}"
                    else
                        __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_GREEN}${S_RADIO_ACTIVE} ${label}${C_RESET}"
                    fi
                else
                    __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}${S_RADIO_INACTIVE} ${label}${C_RESET}"
                fi
            done

            if ((show_bottom_ellipsis == 1)); then
                __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}...${C_RESET}"
            fi
        fi

        __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}↑/↓ select • Enter confirm • Type to search${C_RESET}"
        __clack_print "${C_CYAN}${S_BAR_END}${C_RESET}"

        __clack_read_key

        if [[ "$CLACK_KEY" == "CTRL_C" ]]; then
            __interrupted=1
            __clack_clear_lines $total_lines
            continue
        fi

        case "$CLACK_KEY" in
            UP)
                is_navigating=1
                ((cursor--))
                ((cursor < 0)) && cursor=$((filtered_count - 1))
                ((cursor < 0)) && cursor=0
                ;;
            DOWN)
                is_navigating=1
                ((cursor++))
                ((cursor >= filtered_count)) && cursor=0
                ;;
            ENTER)
                if ((filtered_count > 0)); then
                    break
                fi
                ;;
            BACKSPACE)
                is_navigating=0
                if [[ -n "$input_val" ]]; then
                    input_val="${input_val%?}"
                    __clack_filter_options
                fi
                ;;
            SPACE)
                is_navigating=0
                input_val+=" "
                __clack_filter_options
                ;;
            ESCAPE)
                # Do nothing
                ;;
            *)
                if [[ ${#CLACK_KEY} -eq 1 ]] && [[ "$CLACK_KEY" =~ [[:print:]] ]]; then
                    is_navigating=0
                    input_val+="$CLACK_KEY"
                    __clack_filter_options
                fi
                ;;
        esac

        __clack_clear_lines $total_lines
    done

    __clack_cursor_show
    trap - INT

    local selected_idx=${filtered_indices[$cursor]}
    local selected_label="${opt_labels[$selected_idx]}"
    local selected_value="${opt_values[$selected_idx]}"

    __clack_clear_lines $total_lines
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GREEN}${S_STEP_SUBMIT}${C_RESET}  ${message}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${C_DIM}${selected_label}${C_RESET}"

    printf '%s' "$selected_value"
}

# ============================================================================
# AUTOCOMPLETE MULTISELECT
# ============================================================================

clack_autocomplete_multiselect() {
    local __result_var=$1
    shift
    local message="${1:-Search and select}"
    shift
    local -a options=("$@")
    local count=${#options[@]}
    local input_val=""
    local cursor=0
    local -a opt_values=()
    local -a opt_labels=()
    local -a opt_hints=()
    local -a filtered_indices=()
    local -a selected_map=()
    local __interrupted=0
    local is_navigating=0

    CLACK_CANCELLED=0

    if ((count == 0)); then
        __clack_print "${C_RED}Error: No options provided${C_RESET}"
        return 1
    fi

    # Parse options
    local raw i
    for raw in "${options[@]}"; do
        local __parsed __v __l __h __d
        __parsed=$(__clack_parse_option "$raw")
        IFS="$__CLACK_FIELD_SEP" read -r __v __l __h __d <<<"$__parsed"
        opt_values+=("${__v}")
        opt_labels+=("${__l}")
        opt_hints+=("${__h}")
        selected_map+=(0)
    done

    # Initialize filtered indices
    for ((i = 0; i < count; i++)); do
        filtered_indices+=($i)
    done

    __clack_filter_options_multi() {
        filtered_indices=()
        local search_lower
        search_lower=$(__clack_to_lower "$input_val")

        for ((i = 0; i < count; i++)); do
            if [[ -z "$input_val" ]]; then
                filtered_indices+=($i)
            else
                local label_lower value_lower hint_lower
                label_lower=$(__clack_to_lower "${opt_labels[$i]}")
                value_lower=$(__clack_to_lower "${opt_values[$i]}")
                hint_lower=$(__clack_to_lower "${opt_hints[$i]}")

                if [[ "$label_lower" == *"$search_lower"* ]] || \
                   [[ "$value_lower" == *"$search_lower"* ]] || \
                   [[ "$hint_lower" == *"$search_lower"* ]]; then
                    filtered_indices+=($i)
                fi
            fi
        done

        if ((cursor >= ${#filtered_indices[@]})); then
            cursor=0
        fi
    }

    trap '__interrupted=1' INT
    __clack_cursor_hide

    local max_display=8

    while true; do
        local filtered_count=${#filtered_indices[@]}
        local display_count=$filtered_count
        ((display_count > max_display)) && display_count=$max_display
        local total_lines=$((5 + display_count + 1))

        if ((__interrupted)); then
            __clack_cursor_show
            __clack_handle_cancel
            __clack_clear_lines $total_lines
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
            __clack_print "${C_RED}${S_STEP_CANCEL}${C_RESET}  ${message}"
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
            trap - INT
            return 1
        fi

        # Count selected
        local selected_count=0
        for ((i = 0; i < count; i++)); do
            ((selected_map[i] == 1)) && ((selected_count++))
        done

        __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
        __clack_print "${C_CYAN}${S_STEP_ACTIVE}${C_RESET}  ${message}"
        __clack_print "${C_CYAN}${S_BAR}${C_RESET}"

        # Search input line
        local search_display
        if ((is_navigating == 1)) && [[ -n "$input_val" ]]; then
            search_display="${C_DIM}${input_val}${C_RESET}"
        elif [[ -n "$input_val" ]]; then
            search_display="${input_val}${C_INVERSE} ${C_RESET}"
        else
            search_display="${C_INVERSE} ${C_RESET}"
        fi

        local match_info=""
        if [[ -n "$input_val" ]] && ((filtered_count != count)); then
            match_info=" ${C_DIM}(${filtered_count} match"
            ((filtered_count != 1)) && match_info+="es"
            match_info+=")${C_RESET}"
        fi

        __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}Search:${C_RESET} ${search_display}${match_info}"

        if ((filtered_count == 0)) && [[ -n "$input_val" ]]; then
            __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_YELLOW}No matches found${C_RESET}"
        else
            # Pagination
            local start=0
            if ((cursor >= max_display - 2)) && ((filtered_count > max_display)); then
                start=$((cursor - max_display + 3))
                ((start > filtered_count - max_display)) && start=$((filtered_count - max_display))
                ((start < 0)) && start=0
            fi
            local end=$((start + max_display))
            ((end > filtered_count)) && end=$filtered_count

            local show_top_ellipsis=0
            local show_bottom_ellipsis=0
            ((start > 0)) && show_top_ellipsis=1
            ((end < filtered_count)) && show_bottom_ellipsis=1

            if ((show_top_ellipsis == 1)); then
                __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}...${C_RESET}"
                ((start++))
            fi

            for ((i = start; i < end - show_bottom_ellipsis; i++)); do
                local idx=${filtered_indices[$i]}
                local label="${opt_labels[$idx]}"
                local hint="${opt_hints[$idx]}"
                local is_selected=${selected_map[$idx]}

                local icon
                if ((is_selected == 1)); then
                    icon="${C_GREEN}${S_CHECKBOX_SELECTED}${C_RESET}"
                elif ((i == cursor)); then
                    icon="${C_CYAN}${S_CHECKBOX_ACTIVE}${C_RESET}"
                else
                    icon="${C_DIM}${S_CHECKBOX_INACTIVE}${C_RESET}"
                fi

                if ((i == cursor)); then
                    if [[ -n "$hint" ]]; then
                        __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${icon} ${label} ${C_DIM}(${hint})${C_RESET}"
                    else
                        __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${icon} ${label}"
                    fi
                else
                    __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${icon} ${C_DIM}${label}${C_RESET}"
                fi
            done

            if ((show_bottom_ellipsis == 1)); then
                __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}...${C_RESET}"
            fi
        fi

        __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}↑/↓ nav • Space/Tab select • Enter confirm • Type to search${C_RESET}"
        __clack_print "${C_CYAN}${S_BAR_END}${C_RESET}"

        __clack_read_key

        if [[ "$CLACK_KEY" == "CTRL_C" ]]; then
            __interrupted=1
            __clack_clear_lines $total_lines
            continue
        fi

        case "$CLACK_KEY" in
            UP)
                is_navigating=1
                ((cursor--))
                ((cursor < 0)) && cursor=$((filtered_count - 1))
                ((cursor < 0)) && cursor=0
                ;;
            DOWN)
                is_navigating=1
                ((cursor++))
                ((cursor >= filtered_count)) && cursor=0
                ;;
            SPACE|TAB)
                if ((filtered_count > 0)); then
                    local idx=${filtered_indices[$cursor]}
                    if ((selected_map[idx] == 1)); then
                        selected_map[$idx]=0
                    else
                        selected_map[$idx]=1
                    fi
                fi
                ;;
            ENTER)
                break
                ;;
            BACKSPACE)
                is_navigating=0
                if [[ -n "$input_val" ]]; then
                    input_val="${input_val%?}"
                    __clack_filter_options_multi
                fi
                ;;
            ESCAPE)
                ;;
            *)
                if [[ ${#CLACK_KEY} -eq 1 ]] && [[ "$CLACK_KEY" =~ [[:print:]] ]]; then
                    is_navigating=0
                    input_val+="$CLACK_KEY"
                    __clack_filter_options_multi
                fi
                ;;
        esac

        __clack_clear_lines $total_lines
    done

    __clack_cursor_show
    trap - INT

    # Build result
    eval "${__result_var}=()"
    local -a display_items=()
    for ((i = 0; i < count; i++)); do
        if ((selected_map[i] == 1)); then
            local __q
            printf -v __q '%q' "${opt_values[$i]}"
            eval "${__result_var}+=( ${__q} )"
            display_items+=("${opt_labels[$i]}")
        fi
    done

    local display_text
    if ((${#display_items[@]} == 0)); then
        display_text="${C_DIM}none${C_RESET}"
    else
        display_text="${C_DIM}${selected_count} items selected${C_RESET}"
    fi

    __clack_clear_lines $total_lines
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GREEN}${S_STEP_SUBMIT}${C_RESET}  ${message}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${display_text}"
}

# ============================================================================
# PATH PROMPT (File/directory path with autocomplete)
# ============================================================================

clack_path() {
    local message="${1:-Enter path}"
    local initial_value="${2:-$(pwd)}"
    local directory_only="${3:-false}"
    local input_val="$initial_value"
    local cursor=0
    local -a suggestions=()
    local __interrupted=0
    local is_navigating=0

    CLACK_CANCELLED=0

    __clack_get_path_suggestions() {
        suggestions=()
        [[ -z "$input_val" ]] && return

        local search_path
        if [[ -d "$input_val" ]]; then
            search_path="$input_val"
        else
            search_path=$(dirname "$input_val" 2>/dev/null)
        fi

        [[ ! -d "$search_path" ]] && return

        local item
        while IFS= read -r -d '' item; do
            local full_path="${item}"
            if [[ "$full_path" == "$input_val"* ]] || [[ -z "$input_val" ]] || [[ "$input_val" == "$search_path" ]] || [[ "$input_val" == "$search_path/" ]]; then
                if [[ "$directory_only" == "true" ]]; then
                    [[ -d "$full_path" ]] && suggestions+=("$full_path")
                else
                    suggestions+=("$full_path")
                fi
            fi
        done < <(find "$search_path" -maxdepth 1 -mindepth 1 -print0 2>/dev/null | sort -z)

        # Filter to match input
        if [[ -n "$input_val" ]] && [[ "$input_val" != "$search_path" ]] && [[ "$input_val" != "$search_path/" ]]; then
            local -a filtered=()
            for item in "${suggestions[@]}"; do
                if [[ "$item" == "$input_val"* ]]; then
                    filtered+=("$item")
                fi
            done
            suggestions=("${filtered[@]}")
        fi
    }

    __clack_get_path_suggestions

    trap '__interrupted=1' INT
    __clack_cursor_hide

    local max_display=5

    while true; do
        local suggestion_count=${#suggestions[@]}
        local display_count=$suggestion_count
        ((display_count > max_display)) && display_count=$max_display
        local total_lines=$((5 + display_count + 1))

        if ((__interrupted)); then
            __clack_cursor_show
            __clack_handle_cancel
            __clack_clear_lines $total_lines
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
            __clack_print "${C_RED}${S_STEP_CANCEL}${C_RESET}  ${message}"
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${C_DIM}${C_STRIKETHROUGH}${input_val}${C_RESET}"
            trap - INT
            return 1
        fi

        __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
        __clack_print "${C_CYAN}${S_STEP_ACTIVE}${C_RESET}  ${message}"
        __clack_print "${C_CYAN}${S_BAR}${C_RESET}"

        # Path input line
        local path_display
        if ((is_navigating == 1)); then
            path_display="${C_DIM}${input_val}${C_RESET}"
        else
            path_display="${input_val}${C_INVERSE} ${C_RESET}"
        fi

        __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}Path:${C_RESET} ${path_display}"

        if ((suggestion_count > 0)); then
            # Pagination for suggestions
            local start=0
            if ((cursor >= max_display - 1)) && ((suggestion_count > max_display)); then
                start=$((cursor - max_display + 2))
                ((start > suggestion_count - max_display)) && start=$((suggestion_count - max_display))
                ((start < 0)) && start=0
            fi
            local end=$((start + max_display))
            ((end > suggestion_count)) && end=$suggestion_count

            local show_top_ellipsis=0
            local show_bottom_ellipsis=0
            ((start > 0)) && show_top_ellipsis=1
            ((end < suggestion_count)) && show_bottom_ellipsis=1

            if ((show_top_ellipsis == 1)); then
                __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}...${C_RESET}"
                ((start++))
            fi

            local i
            for ((i = start; i < end - show_bottom_ellipsis; i++)); do
                local path="${suggestions[$i]}"
                local display_path="${path}"

                # Add trailing / for directories
                [[ -d "$path" ]] && display_path="${path}/"

                if ((i == cursor)); then
                    __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_GREEN}${S_RADIO_ACTIVE} ${display_path}${C_RESET}"
                else
                    __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}${S_RADIO_INACTIVE} ${display_path}${C_RESET}"
                fi
            done

            if ((show_bottom_ellipsis == 1)); then
                __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}...${C_RESET}"
            fi
        fi

        __clack_print "${C_CYAN}${S_BAR}${C_RESET}  ${C_DIM}↑/↓ select • Tab complete • Enter confirm${C_RESET}"
        __clack_print "${C_CYAN}${S_BAR_END}${C_RESET}"

        __clack_read_key

        if [[ "$CLACK_KEY" == "CTRL_C" ]]; then
            __interrupted=1
            __clack_clear_lines $total_lines
            continue
        fi

        case "$CLACK_KEY" in
            UP)
                is_navigating=1
                ((cursor--))
                ((cursor < 0)) && cursor=$((suggestion_count - 1))
                ((cursor < 0)) && cursor=0
                ;;
            DOWN)
                is_navigating=1
                ((cursor++))
                ((cursor >= suggestion_count)) && cursor=0
                ;;
            TAB)
                # Auto-complete with selected suggestion
                if ((suggestion_count > 0)); then
                    input_val="${suggestions[$cursor]}"
                    [[ -d "$input_val" ]] && input_val="${input_val}/"
                    cursor=0
                    is_navigating=0
                    __clack_get_path_suggestions
                fi
                ;;
            ENTER)
                if ((is_navigating == 1)) && ((suggestion_count > 0)); then
                    input_val="${suggestions[$cursor]}"
                fi
                break
                ;;
            BACKSPACE)
                is_navigating=0
                if [[ -n "$input_val" ]]; then
                    input_val="${input_val%?}"
                    cursor=0
                    __clack_get_path_suggestions
                fi
                ;;
            ESCAPE)
                is_navigating=0
                ;;
            *)
                if [[ ${#CLACK_KEY} -eq 1 ]] && [[ "$CLACK_KEY" =~ [[:print:]] ]]; then
                    is_navigating=0
                    input_val+="$CLACK_KEY"
                    cursor=0
                    __clack_get_path_suggestions
                fi
                ;;
        esac

        __clack_clear_lines $total_lines
    done

    __clack_cursor_show
    trap - INT

    __clack_clear_lines $total_lines
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GREEN}${S_STEP_SUBMIT}${C_RESET}  ${message}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${C_DIM}${input_val}${C_RESET}"

    printf '%s' "$input_val"
}

# ============================================================================
# STREAM (Streaming text output with word wrapping)
# ============================================================================

# Usage: echo "word1 word2 word3" | clack_stream_message
# Or: clack_stream_message "word1" "word2" "word3"

clack_stream_message() {
    local symbol="${C_GRAY}${S_BAR}${C_RESET}"
    local prefix="${C_GRAY}${S_BAR}${C_RESET}  "

    local cols
    cols=$(tput cols 2>/dev/null || printf '80')
    local max_width=$((cols - 5))
    local line_width=0

    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print_n "${symbol}  "
    line_width=3

    if (($# > 0)); then
        # Arguments mode
        local word
        for word in "$@"; do
            local word_len=${#word}
            if ((line_width + word_len + 1 > max_width)); then
                __clack_print ""
                __clack_print_n "${prefix}"
                line_width=3
            fi
            __clack_print_n "${word} "
            line_width=$((line_width + word_len + 1))
            sleep 0.02
        done
    else
        # Stdin mode
        local word
        while IFS= read -r -d ' ' word || [[ -n "$word" ]]; do
            # Handle newlines in word
            if [[ "$word" == *$'\n'* ]]; then
                local part
                local first=1
                while IFS= read -r part; do
                    if ((first == 0)); then
                        __clack_print ""
                        __clack_print_n "${prefix}"
                        line_width=3
                    fi
                    first=0
                    local part_len=${#part}
                    if ((line_width + part_len > max_width)); then
                        __clack_print ""
                        __clack_print_n "${prefix}"
                        line_width=3
                    fi
                    __clack_print_n "${part} "
                    line_width=$((line_width + part_len + 1))
                    sleep 0.02
                done <<<"$word"
            else
                local word_len=${#word}
                if ((line_width + word_len + 1 > max_width)); then
                    __clack_print ""
                    __clack_print_n "${prefix}"
                    line_width=3
                fi
                __clack_print_n "${word} "
                line_width=$((line_width + word_len + 1))
                sleep 0.02
            fi
        done
    fi

    __clack_print ""
}

