# ============================================================================
# TASK LOG (Task with live log output)
# ============================================================================
# Supports groups like TypeScript version:
#   clack_tasklog_start "Task title" [limit]
#   clack_tasklog_message "message"
#   clack_tasklog_group "Group Name"    # Start a named group
#   clack_tasklog_group_message "msg"   # Message in current group
#   clack_tasklog_group_success "msg"   # Complete group with success
#   clack_tasklog_group_error "msg"     # Complete group with error
#   clack_tasklog_success "Done"
#   clack_tasklog_error "Failed"

__CLACK_TASKLOG_LINES=()
__CLACK_TASKLOG_TITLE=""
__CLACK_TASKLOG_LIMIT=10
__CLACK_TASKLOG_LINE_COUNT=0
__CLACK_TASKLOG_GROUPS=()
__CLACK_TASKLOG_CURRENT_GROUP=""

clack_tasklog_start() {
    local title="${1:-Running task}"
    local limit="${2:-10}"

    __CLACK_TASKLOG_TITLE="$title"
    __CLACK_TASKLOG_LIMIT=$limit
    __CLACK_TASKLOG_LINES=()
    __CLACK_TASKLOG_LINE_COUNT=0
    __CLACK_TASKLOG_GROUPS=()
    __CLACK_TASKLOG_CURRENT_GROUP=""

    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GREEN}${S_STEP_SUBMIT}${C_RESET}  ${title}"
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
}

clack_tasklog_message() {
    local msg="$1"
    local raw="${2:-false}"

    # Add message to buffer
    if [[ "$raw" == "true" ]] && ((${#__CLACK_TASKLOG_LINES[@]} > 0)); then
        # Append to last line for raw mode
        local last_idx=$((${#__CLACK_TASKLOG_LINES[@]} - 1))
        __CLACK_TASKLOG_LINES[$last_idx]+="$msg"
    else
        __CLACK_TASKLOG_LINES+=("$msg")
    fi

    # Trim if over limit
    while ((${#__CLACK_TASKLOG_LINES[@]} > __CLACK_TASKLOG_LIMIT)); do
        __CLACK_TASKLOG_LINES=("${__CLACK_TASKLOG_LINES[@]:1}")
    done

    # Clear and redraw
    local line_count=$((${#__CLACK_TASKLOG_LINES[@]} + 1))
    if ((__CLACK_TASKLOG_LINE_COUNT > 0)); then
        __clack_clear_lines $__CLACK_TASKLOG_LINE_COUNT
    fi

    for line in "${__CLACK_TASKLOG_LINES[@]}"; do
        __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${C_DIM}${line}${C_RESET}"
    done
    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"

    __CLACK_TASKLOG_LINE_COUNT=$line_count
}

clack_tasklog_success() {
    local msg="${1:-Done}"
    local show_log="${2:-false}"

    # Clear the log output
    if ((__CLACK_TASKLOG_LINE_COUNT > 0)); then
        __clack_clear_lines $((__CLACK_TASKLOG_LINE_COUNT + 3))
    fi

    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_GREEN}${S_SUCCESS}${C_RESET}  ${msg}"

    if [[ "$show_log" == "true" ]] && ((${#__CLACK_TASKLOG_LINES[@]} > 0)); then
        for line in "${__CLACK_TASKLOG_LINES[@]}"; do
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${C_DIM}${line}${C_RESET}"
        done
    fi

    __CLACK_TASKLOG_LINES=()
    __CLACK_TASKLOG_LINE_COUNT=0
}

clack_tasklog_error() {
    local msg="${1:-Error}"
    local show_log="${2:-true}"

    # Clear the log output
    if ((__CLACK_TASKLOG_LINE_COUNT > 0)); then
        __clack_clear_lines $((__CLACK_TASKLOG_LINE_COUNT + 3))
    fi

    __clack_print "${C_GRAY}${S_BAR}${C_RESET}"
    __clack_print "${C_RED}${S_ERROR}${C_RESET}  ${msg}"

    if [[ "$show_log" == "true" ]] && ((${#__CLACK_TASKLOG_LINES[@]} > 0)); then
        for line in "${__CLACK_TASKLOG_LINES[@]}"; do
            __clack_print "${C_GRAY}${S_BAR}${C_RESET}  ${C_DIM}${line}${C_RESET}"
        done
    fi

    __CLACK_TASKLOG_LINES=()
    __CLACK_TASKLOG_LINE_COUNT=0
}

# Helper to run a command and capture output to task log
clack_tasklog_run() {
    local cmd="$1"

    while IFS= read -r line; do
        clack_tasklog_message "$line"
    done < <(eval "$cmd" 2>&1)

    return ${PIPESTATUS[0]}
}

# Start a named group within the task log
clack_tasklog_group() {
    local name="$1"
    __CLACK_TASKLOG_CURRENT_GROUP="$name"
    __CLACK_TASKLOG_GROUPS+=("header:$name")
    clack_tasklog_message "${C_BOLD}${name}${C_RESET}"
}

# Add message to current group
clack_tasklog_group_message() {
    local msg="$1"
    local raw="${2:-false}"
    if [[ -n "$__CLACK_TASKLOG_CURRENT_GROUP" ]]; then
        clack_tasklog_message "  $msg" "$raw"
    else
        clack_tasklog_message "$msg" "$raw"
    fi
}

# Complete current group with success
clack_tasklog_group_success() {
    local msg="$1"
    if [[ -n "$__CLACK_TASKLOG_CURRENT_GROUP" ]]; then
        __CLACK_TASKLOG_GROUPS+=("success:$__CLACK_TASKLOG_CURRENT_GROUP:$msg")
        clack_tasklog_message "  ${C_GREEN}${S_SUCCESS}${C_RESET} ${msg}"
        __CLACK_TASKLOG_CURRENT_GROUP=""
    fi
}

# Complete current group with error
clack_tasklog_group_error() {
    local msg="$1"
    if [[ -n "$__CLACK_TASKLOG_CURRENT_GROUP" ]]; then
        __CLACK_TASKLOG_GROUPS+=("error:$__CLACK_TASKLOG_CURRENT_GROUP:$msg")
        clack_tasklog_message "  ${C_RED}${S_ERROR}${C_RESET} ${msg}"
        __CLACK_TASKLOG_CURRENT_GROUP=""
    fi
}

# ============================================================================
# CLEANUP
# ============================================================================

__clack_cleanup() {
    __clack_cursor_show
    if [[ -n "$__CLACK_SPINNER_PID" ]]; then
        kill "$__CLACK_SPINNER_PID" 2>/dev/null
    fi
}

trap __clack_cleanup EXIT

# ============================================================================
# VERSION
# ============================================================================

CLACK_VERSION="1.2.0"

clack_version() {
    printf '%s' "$CLACK_VERSION"
}

# src/lib/common.sh
# Shared constants, UI wrappers and session cleanup.

set -eo pipefail

SLOTS=(9a 9c 9d 9e)
SLOT_NAMES=("PIV Authentication" "Digital Signature" "Key Management" "Card Authentication")
DEFAULT_SUBJECTS=("CN=MacOS login" "CN=Digital Signature" "CN=encryption" "CN=Card Authentication")
CHUID_OBJECT="5fc102"

YK_DEVICE=""
YK_PIN=""
TMP_DIR=""

# ---------------------------------------------------------------------------
# Session: temp dir + EXIT trap. Every command calls session_init first.
# ---------------------------------------------------------------------------

session_init() {
  TMP_DIR="$(mktemp -d)"
  trap session_cleanup EXIT
}

session_cleanup() {
  local status=$?
  trap - EXIT
  chuid_restore_on_exit
  YK_PIN=""
  [[ -z "$TMP_DIR" ]] || rm -rf "$TMP_DIR"
  exit "$status"
}

# ---------------------------------------------------------------------------
# UI wrappers around clack. Prompt helpers return their answer in $REPLY and
# abort cleanly on Ctrl+C.
# ---------------------------------------------------------------------------

die() {
  clack_log_error "$*"
  clack_cancel "Aborted."
  exit 1
}

ui_cancel() {
  clack_cancel "Cancelled."
  exit 130
}

# ui_text MESSAGE [DEFAULT] [VALIDATOR_FN]
ui_text() {
  REPLY="$(clack_text "$1" "" "${2:-}" "${3:-}")" || ui_cancel
}

# ui_password MESSAGE  (rejects empty input)
ui_password() {
  while true; do
    REPLY="$(clack_password "$1")" || ui_cancel
    [[ -n "$REPLY" ]] && return 0
    clack_log_warn "Input cannot be empty."
  done
}

# ui_select MESSAGE OPTION...   (OPTION is "value|label|hint|disabled" or plain)
ui_select() {
  REPLY="$(clack_select "$@")" || ui_cancel
}

# ui_multiselect ARRAY_VAR MESSAGE OPTION...  (at least one choice required)
ui_multiselect() {
  local var=$1 n
  while true; do
    clack_multiselect "$@" || ui_cancel
    eval "n=\${#${var}[@]}"
    ((n > 0)) && return 0
    clack_log_warn "Select at least one (space toggles, a selects all)."
  done
}

# ui_confirm MESSAGE [true|false]  -> status 0 for yes, 1 for no
ui_confirm() {
  local answer
  answer="$(clack_confirm "$1" "${2:-true}")" || true
  [[ -n "$answer" ]] || ui_cancel
  [[ "$answer" == true ]]
}

# run_step MESSAGE CMD...  Runs CMD under a spinner; output is shown only on failure.
run_step() {
  local msg=$1
  shift
  local log="$TMP_DIR/step.log"

  clack_spinner_start "$msg"
  if "$@" >"$log" 2>&1; then
    clack_spinner_stop "$msg"
  else
    clack_spinner_error "$msg - failed"
    [[ ! -s "$log" ]] || clack_log_error "$(tail -n 8 "$log")"
    return 1
  fi
}

validate_positive_int() {
  [[ "$1" =~ ^[1-9][0-9]*$ ]] || printf 'Must be a positive integer'
}

validate_nonempty() {
  [[ -n "$1" ]] || printf 'Cannot be empty'
}

# get_flag NAME -> value of --NAME (empty if unset). Keeps `args[--x]` keys out of
# the source, since shfmt would parse them as arithmetic.
get_flag() {
  local key="--$1"
  printf '%s' "${args[$key]:-}"
}

backup_root() {
  local root
  root="$(get_flag backup-root)"
  printf '%s' "${root:-$YBMAN_BACKUP_ROOT}"
}

# ui_note TITLE MULTILINE_TEXT
ui_note() {
  local title=$1 line lines=()
  while IFS= read -r line; do lines+=("$line"); done <<<"$2"
  clack_note "$title" "${lines[@]}"
}

# src/lib/crypto.sh
# OpenSSL helpers for PIV public keys and certificates.

pubkey_fingerprint() {
  openssl pkey -pubin -in "$1" -outform DER 2>/dev/null |
    openssl dgst -sha256 |
    sed -E 's/^.*= //'
}

# Hash for a new self-signed cert: SHA384 for P-384 keys, else SHA256.
hash_for_pubkey() {
  local description
  description="$(openssl pkey -pubin -in "$1" -text -noout 2>/dev/null)"
  case "$description" in
    *secp384r1* | *"P-384"* | *"384 bit"*) printf 'SHA384' ;;
    *) printf 'SHA256' ;;
  esac
}

# Hash used to sign an existing certificate.
hash_from_cert() {
  local algorithm
  algorithm="$(
    openssl x509 -in "$1" -noout -text |
      ugrep --color=never -m1 'Signature Algorithm:' |
      sed -E 's/.*Signature Algorithm:[[:space:]]*//'
  )"
  case "$algorithm" in
    *SHA512* | *sha512*) printf 'SHA512' ;;
    *SHA384* | *sha384*) printf 'SHA384' ;;
    *SHA256* | *sha256*) printf 'SHA256' ;;
    *)
      printf 'unsupported signature algorithm: %s\n' "$algorithm" >&2
      return 1
      ;;
  esac
}

# x509_name subject|issuer CERT  (RFC2253)
x509_name() {
  openssl x509 -in "$2" -noout "-$1" -nameopt RFC2253 | sed -E "s/^$1= ?//"
}

cert_has_extensions() {
  openssl x509 -in "$1" -noout -text | ugrep -q --color=never 'X509v3 extensions:'
}

cert_summary() {
  openssl x509 -in "$1" -noout -subject -issuer -serial -dates -fingerprint -sha256
}

# src/lib/slot_ops.sh
# Per-slot operations. These run under run_step (an `if` context where errexit
# is disabled), so every command is checked explicitly.

# slot_classify SERIAL -> fills SLOT_STATE[] (complete|key-only|certificate-only|empty)
SLOT_STATE=()
slot_classify() {
  local serial=$1 i slot key cert
  SLOT_STATE=()
  for i in "${!SLOTS[@]}"; do
    slot="${SLOTS[$i]}"
    key=0 cert=0
    yk "$serial" piv keys info "$slot" >/dev/null 2>&1 && key=1
    yk "$serial" piv certificates export "$slot" "$TMP_DIR/$slot-existing.pem" >/dev/null 2>&1 && cert=1
    if ((key && cert)); then
      SLOT_STATE[i]="complete"
    elif ((key)); then
      SLOT_STATE[i]="key-only"
    elif ((cert)); then
      SLOT_STATE[i]="certificate-only"
    else
      SLOT_STATE[i]="empty"
    fi
  done
}

# provision_slot SERIAL SLOT STATE SUBJECT ALGORITHM DAYS
provision_slot() {
  local serial=$1 slot=$2 state=$3 subject=$4 algorithm=$5 days=$6
  local pub="$TMP_DIR/$slot-public.pem" ver="$TMP_DIR/$slot-verified-public.pem"
  local cert="$TMP_DIR/$slot-certificate.pem" cpub="$TMP_DIR/$slot-certificate-public.pem"
  local hash fp_orig fp_ver fp_cert

  if [[ "$state" == empty ]]; then
    yk "$serial" piv keys generate --pin "$YK_PIN" --algorithm "$algorithm" "$slot" "$pub" || return 1
  else
    yk "$serial" piv keys export --pin "$YK_PIN" --verify "$slot" "$pub" || return 1
  fi

  hash="$(hash_for_pubkey "$pub")"
  chuid_mark_dirty
  yk "$serial" piv certificates generate --pin "$YK_PIN" --subject "$subject" \
    --valid-days "$days" --hash-algorithm "$hash" "$slot" "$pub" || return 1
  yk "$serial" piv certificates export "$slot" "$cert" || return 1
  yk "$serial" piv keys export --pin "$YK_PIN" --verify "$slot" "$ver" || return 1

  fp_orig="$(pubkey_fingerprint "$pub")"
  fp_ver="$(pubkey_fingerprint "$ver")"
  [[ "$fp_orig" == "$fp_ver" ]] || {
    echo "private/public-key verification failed for slot $slot" >&2
    return 1
  }
  openssl x509 -in "$cert" -pubkey -noout >"$cpub" || return 1
  fp_cert="$(pubkey_fingerprint "$cpub")"
  [[ "$fp_orig" == "$fp_cert" ]] || {
    echo "certificate public key does not match slot $slot" >&2
    return 1
  }
}

# refresh_preflight SERIAL SLOT DIR
# Requires DIR/SLOT-cert.pem from write_snapshot. Verifies the key, refuses
# CA-issued or extension-bearing certs, records subject and hash.
refresh_preflight() {
  local serial=$1 slot=$2 dir=$3
  local cert="$dir/$slot-cert.pem" pub="$dir/$slot-pubkey-verified.pem"
  local subject issuer hash

  yk "$serial" piv keys export --pin "$YK_PIN" --verify "$slot" "$pub" || return 1

  subject="$(x509_name subject "$cert")"
  issuer="$(x509_name issuer "$cert")"
  [[ "$subject" == "$issuer" ]] || {
    printf 'slot %s is not self-issued (subject: %s, issuer: %s); refusing to replace a CA-issued certificate\n' \
      "$slot" "$subject" "$issuer" >&2
    return 1
  }
  ! cert_has_extensions "$cert" || {
    echo "slot $slot certificate has X.509 extensions that ykman cannot preserve; refusing" >&2
    return 1
  }
  hash="$(hash_from_cert "$cert")" || return 1

  printf '%s\n' "$subject" >"$dir/$slot-subject.txt"
  printf '%s\n' "$hash" >"$dir/$slot-hash.txt"
  cert_summary "$cert" >"$dir/$slot-cert-old-info.txt"
}

# refresh_slot SERIAL SLOT DIR DAYS
refresh_slot() {
  local serial=$1 slot=$2 dir=$3 days=$4
  local pub="$dir/$slot-pubkey-verified.pem" pub_new="$dir/$slot-pubkey-new.pem"
  local cert_new="$dir/$slot-cert-new.pem" subject hash

  subject="$(<"$dir/$slot-subject.txt")"
  hash="$(<"$dir/$slot-hash.txt")"

  chuid_mark_dirty
  yk "$serial" piv certificates generate --pin "$YK_PIN" --subject "$subject" \
    --valid-days "$days" --hash-algorithm "$hash" "$slot" "$pub" || return 1
  yk "$serial" piv certificates export "$slot" "$cert_new" || return 1
  yk "$serial" piv keys export --pin "$YK_PIN" --verify "$slot" "$pub_new" || return 1

  [[ "$(pubkey_fingerprint "$pub")" == "$(pubkey_fingerprint "$pub_new")" ]] || {
    echo "public key changed unexpectedly in slot $slot" >&2
    return 1
  }
  cert_summary "$cert_new" >"$dir/$slot-cert-new-info.txt"
}

# src/lib/yk.sh
# YubiKey discovery and selection.

YK_SERIALS=()

yk_list() {
  YK_SERIALS=()
  local serial
  while IFS= read -r serial; do
    [[ -z "$serial" ]] || YK_SERIALS+=("$serial")
  done < <(ykman list --serials 2>/dev/null)
  ((${#YK_SERIALS[@]} > 0)) || die "no YubiKeys found"
}

# yk_field SERIAL "Device type" -> value from `ykman info`
yk_field() {
  ykman --device "$1" info 2>/dev/null |
    sed -n "s/^$2:[[:space:]]*//p" | sed -n '1p'
}

# yk_option SERIAL -> "serial|label|hint" for clack select
yk_option() {
  local type fw
  type="$(yk_field "$1" "Device type")"
  fw="$(yk_field "$1" "Firmware version")"
  printf '%s|%s|%s' "$1" "${type:-Unknown YubiKey}" "serial $1, firmware ${fw:-unknown}"
}

# yk_pick_one -> sets YK_DEVICE (honours --serial)
yk_pick_one() {
  yk_list
  if [[ -n "$(get_flag serial)" ]]; then
    yk_has_serial "$(get_flag serial)" || die "YubiKey $(get_flag serial) not connected"
    YK_DEVICE="$(get_flag serial)"
    return
  fi
  local options=() s
  for s in "${YK_SERIALS[@]}"; do options+=("$(yk_option "$s")"); done
  ui_select "Select a YubiKey" "${options[@]}"
  YK_DEVICE="$REPLY"
}

# yk_pick_many -> sets YK_SELECTED (array; honours --serial)
yk_pick_many() {
  yk_list
  YK_SELECTED=()
  if [[ -n "$(get_flag serial)" ]]; then
    yk_has_serial "$(get_flag serial)" || die "YubiKey $(get_flag serial) not connected"
    YK_SELECTED=("$(get_flag serial)")
    return
  fi
  if ((${#YK_SERIALS[@]} == 1)); then
    YK_SELECTED=("${YK_SERIALS[0]}")
    clack_log_info "Using the only connected YubiKey: $(yk_option "${YK_SERIALS[0]}" | cut -d'|' -f2,3 | tr '|' ' ')"
    return
  fi
  local options=() s
  for s in "${YK_SERIALS[@]}"; do options+=("$(yk_option "$s")"); done
  ui_multiselect YK_SELECTED "Select YubiKeys (space toggles, a selects all)" "${options[@]}"
}

yk_has_serial() {
  local s
  for s in "${YK_SERIALS[@]}"; do [[ "$s" == "$1" ]] && return 0; done
  return 1
}

# yk SERIAL ykman-args...
yk() {
  local serial=$1
  shift
  ykman --device "$serial" "$@"
}

yk_ask_pin() {
  ui_password "PIV PIN"
  YK_PIN="$REPLY"
}

# :command.command_functions
# :command.function
ybman.sh_backup_command() {

  # src/backup_command.sh
  session_init
  clack_intro "ybman backup"

  yk_pick_many

  dirs=()
  for serial in "${YK_SELECTED[@]}"; do
    dir="$(new_backup_dir "$serial")"
    run_step "Backing up YubiKey $serial" write_snapshot "$serial" "$dir" before ||
      die "backup of YubiKey $serial failed"
    dirs+=("$dir")
  done

  clack_note "Backups written" "${dirs[@]}"
  clack_outro "Done"

}

# :command.function
ybman.sh_provision_command() {

  # src/provision_command.sh
  session_init
  clack_intro "ybman provision"

  yk_pick_one
  device="$YK_DEVICE"

  yk "$device" piv info >/dev/null 2>&1 || die "PIV is not available on YubiKey $device"
  ui_note "YubiKey $device" "$(yk "$device" info 2>/dev/null | sed -n '1,8p')"

  # --- inspect slots ---------------------------------------------------------
  slot_classify "$device"
  lines=()
  actions=0
  for i in "${!SLOTS[@]}"; do
    lines+=("$(printf '%-3s %-20s %s' "${SLOTS[$i]}" "${SLOT_NAMES[$i]}" "${SLOT_STATE[$i]}")")
    case "${SLOT_STATE[$i]}" in
      certificate-only) die "slot ${SLOTS[$i]} has a certificate but no detectable private key" ;;
      complete) ;;
      *) actions=$((actions + 1)) ;;
    esac
  done
  clack_note "PIV slots" "${lines[@]}"

  if ((actions == 0)); then
    clack_outro "All four primary PIV slots are already populated."
    exit 0
  fi

  # --- wizard ----------------------------------------------------------------
  algorithm="$(get_flag algorithm)"
  valid_days="$(get_flag valid-days)"
  subjects=()
  for i in "${!SLOTS[@]}"; do subjects[i]=""; done

  if [[ -z "$(get_flag yes)" ]]; then
    clack_log_info "New private keys are generated on the YubiKey. Existing keys are never replaced."
    other=ECCP256
    [[ "$algorithm" == ECCP256 ]] && other=ECCP384
    ui_select "Algorithm for new keys" "$algorithm" "$other"
    algorithm="$REPLY"
    ui_text "Certificate validity in days" "$valid_days" validate_positive_int
    valid_days="$REPLY"
    for i in "${!SLOTS[@]}"; do
      [[ "${SLOT_STATE[$i]}" != complete ]] || continue
      ui_text "${SLOTS[$i]} ${SLOT_NAMES[$i]} subject" "${DEFAULT_SUBJECTS[$i]}" validate_nonempty
      subjects[i]="$REPLY"
    done
  else
    for i in "${!SLOTS[@]}"; do subjects[i]="${DEFAULT_SUBJECTS[$i]}"; done
  fi

  # --- plan ------------------------------------------------------------------
  plan=("Device:    $device" "Algorithm: $algorithm" "Validity:  $valid_days days (~$((valid_days / 365)) years)" "")
  for i in "${!SLOTS[@]}"; do
    case "${SLOT_STATE[$i]}" in
      complete) plan+=("${SLOTS[$i]}  leave unchanged") ;;
      key-only) plan+=("${SLOTS[$i]}  keep key, create certificate  (${subjects[$i]})") ;;
      empty) plan+=("${SLOTS[$i]}  generate $algorithm key + certificate  (${subjects[$i]})") ;;
    esac
  done
  clack_note "Plan" "${plan[@]}"

  if [[ -z "$(get_flag yes)" ]]; then
    ui_confirm "Configure this YubiKey?" false || {
      clack_cancel "Nothing changed."
      exit 0
    }
  fi

  yk_ask_pin

  # --- backup ----------------------------------------------------------------
  backup_dir="$(new_backup_dir "$device")"
  run_step "Backing up current PIV state" write_snapshot "$device" "$backup_dir" before ||
    die "backup failed"
  if chuid_save "$device" "$backup_dir/chuid.bin"; then
    clack_log_success "Saved CHUID"
  else
    clack_log_warn "Unable to export CHUID; it will not be restored"
  fi

  # --- configure -------------------------------------------------------------
  for i in "${!SLOTS[@]}"; do
    [[ "${SLOT_STATE[$i]}" != complete ]] || continue
    run_step "${SLOTS[$i]} ${SLOT_NAMES[$i]}: ${subjects[$i]}" \
      provision_slot "$device" "${SLOTS[$i]}" "${SLOT_STATE[$i]}" "${subjects[$i]}" "$algorithm" "$valid_days" ||
      die "provisioning slot ${SLOTS[$i]} failed (backup: $backup_dir)"
  done

  if [[ -n "$CHUID_FILE" ]]; then
    run_step "Restoring original CHUID" chuid_restore || die "CHUID restore failed (original: $backup_dir/chuid.bin)"
  fi

  yk "$device" piv info >"$backup_dir/piv-info-after.txt"
  ui_note "Final PIV state" "$(<"$backup_dir/piv-info-after.txt")"
  clack_outro "Done. Backup: $backup_dir"

}

# :command.function
ybman.sh_refresh_command() {

  # src/refresh_command.sh
  session_init
  clack_intro "ybman refresh"

  yk_pick_many

  valid_days="$(get_flag valid-days)"
  if [[ -z "$(get_flag yes)" ]]; then
    ui_text "New certificate validity in days" "$valid_days" validate_positive_int
    valid_days="$REPLY"
  fi

  refreshed=()
  for serial in "${YK_SELECTED[@]}"; do
    clack_log_step "YubiKey $serial"
    YK_DEVICE="$serial"
    yk_ask_pin

    dir="$(new_backup_dir "$serial")"
    run_step "Backing up current PIV state" write_snapshot "$serial" "$dir" before ||
      die "backup failed"
    chuid_save "$serial" "$dir/chuid.bin" || die "unable to export CHUID; refusing to continue"

    # --- preflight ---
    active=()
    plan=()
    for slot in "${SLOTS[@]}"; do
      if [[ ! -f "$dir/$slot-cert.pem" ]]; then
        plan+=("$slot  no certificate; skipped")
        continue
      fi
      run_step "Verifying slot $slot" refresh_preflight "$serial" "$slot" "$dir" ||
        die "slot $slot on YubiKey $serial cannot be refreshed"
      active+=("$slot")
      plan+=("$slot  $(<"$dir/$slot-subject.txt")  [$(<"$dir/$slot-hash.txt")]")
    done

    if ((${#active[@]} == 0)); then
      clack_log_warn "No certificates to refresh on YubiKey $serial"
      chuid_forget
      continue
    fi

    clack_note "Refresh plan ($serial, $valid_days days, keys unchanged)" "${plan[@]}"
    if [[ -z "$(get_flag yes)" ]]; then
      ui_confirm "Replace these certificates?" false || {
        clack_log_info "Skipped YubiKey $serial"
        chuid_forget
        continue
      }
    fi

    # --- refresh ---
    for slot in "${active[@]}"; do
      run_step "Refreshing slot $slot" refresh_slot "$serial" "$slot" "$dir" "$valid_days" ||
        die "refreshing slot $slot failed (backup: $dir)"
    done
    run_step "Restoring original CHUID" chuid_restore || die "CHUID restore failed (original: $dir/chuid.bin)"
    chuid_forget
    yk "$serial" piv info >"$dir/piv-info-after.txt"

    results=()
    for slot in "${active[@]}"; do
      results+=("$slot  $(sed -n 's/^notAfter=/valid until /p' "$dir/$slot-cert-new-info.txt")")
    done
    clack_note "Refreshed $serial" "${results[@]}"
    refreshed+=("$dir")
    YK_PIN=""
  done

  clack_outro "Done. ${#refreshed[@]} YubiKey(s) refreshed."

}

# :command.parse_requirements
parse_requirements() {
  local key

  # :command.fixed_flags_filter
  while [[ $# -gt 0 ]]; do
    key="$1"
    case "$key" in
      --version | -v)
        version_command
        exit
        ;;

      --help | -h)
        long_usage=yes
        ybman.sh_usage
        exit
        ;;

      *)
        break
        ;;

    esac
  done

  # :command.environment_variables_filter
  # :command.environment_variables_default
  export YBMAN_BACKUP_ROOT="${YBMAN_BACKUP_ROOT:-./yubikey-piv-backups}"

  env_var_names+=("YBMAN_BACKUP_ROOT")

  # :command.command_filter
  action=${1:-}

  case $action in
    -*) ;;

    backup | b)
      action="backup"
      shift
      ybman.sh_backup_parse_requirements "$@"
      shift $#
      ;;

    provision | p)
      action="provision"
      shift
      ybman.sh_provision_parse_requirements "$@"
      shift $#
      ;;

    refresh | r)
      action="refresh"
      shift
      ybman.sh_refresh_parse_requirements "$@"
      shift $#
      ;;

    # :command.command_fallback
    "")
      ybman.sh_usage >&2
      exit 1
      ;;

    *)
      printf "invalid command: %s\n" "$action" >&2
      exit 1
      ;;

  esac

  # :command.parse_requirements_while
  while [[ $# -gt 0 ]]; do
    key="$1"
    case "$key" in

      --)
        shift
        while [[ $# -gt 0 ]]; do
          key="$1"
          # :command.parse_requirements_case
          # :command.parse_requirements_case_simple
          printf "invalid argument: %s\n" "$key" >&2
          exit 1

        done
        break
        ;;

      -?*)
        printf "invalid option: %s\n" "$key" >&2
        exit 1
        ;;

      *)
        # :command.parse_requirements_case
        # :command.parse_requirements_case_simple
        printf "invalid argument: %s\n" "$key" >&2
        exit 1

        ;;

    esac
  done

}

# :command.parse_requirements
ybman.sh_backup_parse_requirements() {
  local key

  # :command.fixed_flags_filter
  while [[ $# -gt 0 ]]; do
    key="$1"
    case "$key" in
      --help | -h)
        long_usage=yes
        ybman.sh_backup_usage
        exit
        ;;

      *)
        break
        ;;

    esac
  done

  # :command.dependencies_filter
  missing_deps=
  # :dependency.filter
  if ! command -v ykman >/dev/null 2>&1; then
    printf "missing dependency: ykman\n" >&2
    missing_deps=1
  else
    deps['ykman']="$(command -v ykman | head -n1)"
  fi

  if [[ -n $missing_deps ]]; then
    exit 1
  fi

  # :command.command_filter
  action="backup"

  # :command.parse_requirements_while
  while [[ $# -gt 0 ]]; do
    key="$1"
    case "$key" in
      # :flag.case
      --backup-root)

        # :flag.case_arg
        if [[ -n ${2+x} ]]; then
          args['--backup-root']="$2"
          shift
          shift
        else
          printf "%s\n" "--backup-root requires an argument: --backup-root DIR" >&2
          exit 1
        fi
        ;;

      # :flag.case
      --serial | -s)

        # :flag.case_arg
        if [[ -n ${2+x} ]]; then
          args['--serial']="$2"
          shift
          shift
        else
          printf "%s\n" "--serial requires an argument: --serial, -s SERIAL" >&2
          exit 1
        fi
        ;;

      --)
        shift
        while [[ $# -gt 0 ]]; do
          key="$1"
          # :command.parse_requirements_case
          # :command.parse_requirements_case_simple
          printf "invalid argument: %s\n" "$key" >&2
          exit 1

        done
        break
        ;;

      -?*)
        printf "invalid option: %s\n" "$key" >&2
        exit 1
        ;;

      *)
        # :command.parse_requirements_case
        # :command.parse_requirements_case_simple
        printf "invalid argument: %s\n" "$key" >&2
        exit 1

        ;;

    esac
  done

}

# :command.parse_requirements
ybman.sh_provision_parse_requirements() {
  local key

  # :command.fixed_flags_filter
  while [[ $# -gt 0 ]]; do
    key="$1"
    case "$key" in
      --help | -h)
        long_usage=yes
        ybman.sh_provision_usage
        exit
        ;;

      *)
        break
        ;;

    esac
  done

  # :command.dependencies_filter
  missing_deps=
  # :dependency.filter
  if ! command -v ykman >/dev/null 2>&1; then
    printf "missing dependency: ykman\n" >&2
    missing_deps=1
  else
    deps['ykman']="$(command -v ykman | head -n1)"
  fi

  # :dependency.filter
  if ! command -v openssl >/dev/null 2>&1; then
    printf "missing dependency: openssl\n" >&2
    missing_deps=1
  else
    deps['openssl']="$(command -v openssl | head -n1)"
  fi

  # :dependency.filter
  if ! command -v cmp >/dev/null 2>&1; then
    printf "missing dependency: cmp\n" >&2
    missing_deps=1
  else
    deps['cmp']="$(command -v cmp | head -n1)"
  fi

  if [[ -n $missing_deps ]]; then
    exit 1
  fi

  # :command.command_filter
  action="provision"

  # :command.parse_requirements_while
  while [[ $# -gt 0 ]]; do
    key="$1"
    case "$key" in
      # :flag.case
      --backup-root)

        # :flag.case_arg
        if [[ -n ${2+x} ]]; then
          args['--backup-root']="$2"
          shift
          shift
        else
          printf "%s\n" "--backup-root requires an argument: --backup-root DIR" >&2
          exit 1
        fi
        ;;

      # :flag.case
      --serial | -s)

        # :flag.case_arg
        if [[ -n ${2+x} ]]; then
          args['--serial']="$2"
          shift
          shift
        else
          printf "%s\n" "--serial requires an argument: --serial, -s SERIAL" >&2
          exit 1
        fi
        ;;

      # :flag.case
      --algorithm | -a)

        # :flag.case_arg
        if [[ -n ${2+x} ]]; then
          args['--algorithm']="$2"
          shift
          shift
        else
          printf "%s\n" "--algorithm requires an argument: --algorithm, -a ALGORITHM" >&2
          exit 1
        fi
        ;;

      # :flag.case
      --valid-days | -d)

        # :flag.case_arg
        if [[ -n ${2+x} ]]; then
          args['--valid-days']="$2"
          shift
          shift
        else
          printf "%s\n" "--valid-days requires an argument: --valid-days, -d DAYS" >&2
          exit 1
        fi
        ;;

      # :flag.case
      --yes | -y)

        # :flag.case_no_arg
        args['--yes']=1
        shift
        ;;

      --)
        shift
        while [[ $# -gt 0 ]]; do
          key="$1"
          # :command.parse_requirements_case
          # :command.parse_requirements_case_simple
          printf "invalid argument: %s\n" "$key" >&2
          exit 1

        done
        break
        ;;

      -?*)
        printf "invalid option: %s\n" "$key" >&2
        exit 1
        ;;

      *)
        # :command.parse_requirements_case
        # :command.parse_requirements_case_simple
        printf "invalid argument: %s\n" "$key" >&2
        exit 1

        ;;

    esac
  done

  # :command.default_assignments
  [[ -n ${args['--algorithm']:-} ]] || args['--algorithm']="ECCP384"
  [[ -n ${args['--valid-days']:-} ]] || args['--valid-days']="3650"

  # :command.whitelist_filter
  if [[ ${args['--algorithm']:-} ]] && [[ ! ${args['--algorithm']:-} =~ ^(ECCP256|ECCP384)$ ]]; then
    printf "%s\n" "--algorithm must be one of: ECCP256, ECCP384" >&2
    exit 1
  fi

}

# :command.parse_requirements
ybman.sh_refresh_parse_requirements() {
  local key

  # :command.fixed_flags_filter
  while [[ $# -gt 0 ]]; do
    key="$1"
    case "$key" in
      --help | -h)
        long_usage=yes
        ybman.sh_refresh_usage
        exit
        ;;

      *)
        break
        ;;

    esac
  done

  # :command.dependencies_filter
  missing_deps=
  # :dependency.filter
  if ! command -v ykman >/dev/null 2>&1; then
    printf "missing dependency: ykman\n" >&2
    missing_deps=1
  else
    deps['ykman']="$(command -v ykman | head -n1)"
  fi

  # :dependency.filter
  if ! command -v openssl >/dev/null 2>&1; then
    printf "missing dependency: openssl\n" >&2
    missing_deps=1
  else
    deps['openssl']="$(command -v openssl | head -n1)"
  fi

  # :dependency.filter
  if ! command -v ugrep >/dev/null 2>&1; then
    printf "missing dependency: ugrep\n" >&2
    missing_deps=1
  else
    deps['ugrep']="$(command -v ugrep | head -n1)"
  fi

  if [[ -n $missing_deps ]]; then
    exit 1
  fi

  # :command.command_filter
  action="refresh"

  # :command.parse_requirements_while
  while [[ $# -gt 0 ]]; do
    key="$1"
    case "$key" in
      # :flag.case
      --backup-root)

        # :flag.case_arg
        if [[ -n ${2+x} ]]; then
          args['--backup-root']="$2"
          shift
          shift
        else
          printf "%s\n" "--backup-root requires an argument: --backup-root DIR" >&2
          exit 1
        fi
        ;;

      # :flag.case
      --serial | -s)

        # :flag.case_arg
        if [[ -n ${2+x} ]]; then
          args['--serial']="$2"
          shift
          shift
        else
          printf "%s\n" "--serial requires an argument: --serial, -s SERIAL" >&2
          exit 1
        fi
        ;;

      # :flag.case
      --valid-days | -d)

        # :flag.case_arg
        if [[ -n ${2+x} ]]; then
          args['--valid-days']="$2"
          shift
          shift
        else
          printf "%s\n" "--valid-days requires an argument: --valid-days, -d DAYS" >&2
          exit 1
        fi
        ;;

      # :flag.case
      --yes | -y)

        # :flag.case_no_arg
        args['--yes']=1
        shift
        ;;

      --)
        shift
        while [[ $# -gt 0 ]]; do
          key="$1"
          # :command.parse_requirements_case
          # :command.parse_requirements_case_simple
          printf "invalid argument: %s\n" "$key" >&2
          exit 1

        done
        break
        ;;

      -?*)
        printf "invalid option: %s\n" "$key" >&2
        exit 1
        ;;

      *)
        # :command.parse_requirements_case
        # :command.parse_requirements_case_simple
        printf "invalid argument: %s\n" "$key" >&2
        exit 1

        ;;

    esac
  done

  # :command.default_assignments
  [[ -n ${args['--valid-days']:-} ]] || args['--valid-days']="3650"

}

# :command.initialize
initialize() {
  declare -g version="0.1.0"
  set -e

  # :command.environment_variables_default
  export YBMAN_BACKUP_ROOT="${YBMAN_BACKUP_ROOT:-./yubikey-piv-backups}"

  # src/initialize.sh
  # TRACE would echo the PIV PIN into the terminal/log.
  if [[ "${TRACE-0}" == "1" ]]; then
    echo "error: TRACE=1 is not allowed because ybman handles a PIV PIN" >&2
    exit 1
  fi

}

# :command.run
run() {
  # :command.globals
  declare -g long_usage=''
  declare -g -A args=()
  declare -g -A deps=()
  declare -g -a env_var_names=()
  declare -g -a input=()

  normalize_input "$@"
  parse_requirements "${input[@]}"

  case "$action" in
    "backup") ybman.sh_backup_command ;;
    "provision") ybman.sh_provision_command ;;
    "refresh") ybman.sh_refresh_command ;;
  esac
}

# :command.start
start() {
  command_line_args=("$@")
  initialize
  run "${command_line_args[@]}"
}

if [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then
  start "$@"
fi
